-- migrations/2026-07-28_utility_load_requests.sql
--
-- The utility data-centre load register. Schema + the 7 curated rows, so both are
-- reviewable in git rather than living only in the prod DB.
--
-- ★★ WHY THE CITATION CONSTRAINT IS THE POINT — DO NOT REMOVE IT.
-- This table replaces uncited aggregates that were sitting in capacity_pipeline
-- (AEP 63,000 MW, Dominion 48,000, PPL 25,200, "Google 150,000 operational") with
-- NO source, NO url and NO notes — plausible-looking numbers with zero provenance,
-- which is how 67% of a published 2,514 GW figure turned out to be unciteable.
-- source_url is NOT NULL and regex-checked; source_title is NOT NULL; as_of_date is
-- NOT NULL because these figures move quarterly. A row cannot exist without a
-- resolvable citation. Verified by attempting to insert
-- ('AEP', 63, 'no-citation', 'remembered from somewhere') -> rejected.
--
-- ★★ WHAT THE ROWS SHOW (the differentiated asset): every utility's headline is
-- 2-3x what it actually forecasts, and each discloses the discount in its own
-- filing. Oncor 271 raw requests -> 122 forecast (2.2x). Dominion 47 GW contracted
-- capacity -> 16.6 GW forecast demand (2.8x), with 64% of the 47 at the weakest
-- ELOA tier (site control + a $250k deposit). Exelon 18 GW committed but only ~45%
-- TSA-secured. request_type exists SO THESE NEVER COLLAPSE INTO ONE "GW" NUMBER
-- AGAIN -- that collapse is exactly what produced the 2,514 GW figure.
--
-- ★ HOW TO ADD A UTILITY (the path that works): the GW figures live in earnings-deck
-- 8-K EXHIBIT 99.2 on EDGAR -- not in the 10-K/10-Q, and not reliably on corporate
-- IR sites (403/404/JS). Recipe:
--   data.sec.gov/submissions/CIK{10-digit}.json -> filter form=='8-K' for the
--   earnings month -> fetch the accession DIRECTORY listing -> grep href=".*ex99.*\.htm"
--   -> fetch -> regex ([0-9.,]+)\s?(GW|gigawatt) with a +/-250 char context window
--   requiring data cent|pipeline|committed|queue|study phase -> paste the sentence
--   VERBATIM into notes. EDGAR requires a descriptive User-Agent; sleep ~0.4s.
-- Never cite a search snippet. No primary figure => no row. Rejected on that basis:
-- PPL (4 conflicting figures in coverage, none in its release or 8-K), Entergy
-- (states the GENERATION built for Meta, never Meta's load), Duke (May-2026 8-K has
-- zero data-centre mentions).

CREATE TABLE IF NOT EXISTS utility_load_requests (
    id              BIGSERIAL PRIMARY KEY,
    utility         TEXT NOT NULL,
    state           TEXT,
    iso             TEXT,
    gw_requested    DOUBLE PRECISION NOT NULL CHECK (gw_requested > 0 AND gw_requested < 500),
    as_of_date      DATE NOT NULL,
    source_url      TEXT NOT NULL CHECK (source_url ~* '^https?://.+\..+'),
    source_title    TEXT NOT NULL,
    filing_type     TEXT,
    request_type    TEXT,
    notes           TEXT,
    verified_by     TEXT,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (utility, as_of_date, gw_requested)
);
CREATE INDEX IF NOT EXISTS ix_ulr_utility ON utility_load_requests(utility);
CREATE INDEX IF NOT EXISTS ix_ulr_asof    ON utility_load_requests(as_of_date DESC);

-- ── curated rows (7) ────────────────────────────────────────────────────────
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Oncor Electric Delivery','TX','ERCOT',271,'2026-03-31','https://www.oncor.com/content/oncorwww/wire/en/home/newsroom/oncor-reports-first-quarter-2026-results.html','Oncor Reports First Quarter 2026 Results, interconnection-queue paragraph','quarterly results','RAW interconnection REQUESTS from data centres','VERBATIM: "Oncor''s active transmission LC&I interconnection queue included 697 requests at the end of the first quarter of 2026. Those requests included approximately 271 gigawatts from data centers and over 18 gigawatts of load from various other industrial sectors." ★★SECONDARY SOURCES WERE STALE/WRONG: coverage reported 186 GW and ~200 GW; the primary says 271 GW. Cite the filing, not the article. ★Pair with the 122 GW row: Oncor''s own ERCOT RTP forecast is 2.2x SMALLER than its raw queue — the same capacity-vs-demand gap Dominion flags (47 vs 16.6).','claude-opus-5 2026-07-28 (page fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Oncor Electric Delivery','TX','ERCOT',122,'2026-04-01','https://www.oncor.com/content/oncorwww/wire/en/home/newsroom/oncor-reports-first-quarter-2026-results.html','Oncor Reports First Quarter 2026 Results, ERCOT 2026 RTP submission paragraph','ERCOT Regional Transmission Plan submission','FORECAST large load through 2036 (the filtered number)','VERBATIM: "On April 1, 2026, Oncor submitted 122 gigawatts of large load forecast data and 5.2 gigawatts of medium load forecast data through 2036 for inclusion in the Electric Reliability Council of Texas'' ("ERCOT") 2026 Regional Transmission Plan." ★This is what Oncor actually FORECASTS vs 271 GW of raw requests — quote 122 for planning, 271 only as queue volume, never interchangeably.','claude-opus-5 2026-07-28 (page fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('American Electric Power','multi (11-state)','PJM/SPP/ERCOT',63,'2026-07-28','https://www.aep.com/investors','AEP Investors page, Investment Highlights — "Best-in-Class Load Growth: An additional 63GW by 2030, backed by signed customer financial commitments"','investor relations','committed new load (not a request queue)','VERBATIM: "Our five-year, $78 billion capital plan and 63 GW of new load by 2030, backed by signed agreements". ★SEMANTICS: this is COMMITTED/CONTRACTED new load by 2030 backed by signed customer financial commitments — NOT an interconnection-request queue, and NOT data-centre-only. Do not restate it as "63 GW of data centre requests". Checked AEP 10-Q (2026-05-05): mentions data centres ONCE, about new large-load tariff filings, with NO GW figure — so the SEC filings do not carry this number.','claude-opus-5 2026-07-28 (fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Dominion Energy Virginia','VA','PJM',47,'2025-07-01','https://www.pjm.com/-/media/DotCom/planning/res-adeq/load-forecast/dominion-documentation.pdf','Letter, Stan Blackwell (Director - Data Center Practice, Dominion Energy) to PJM Load Analysis Team, 2026-01-06, section "Contract Structure" / summary','load-forecast submission to PJM','contracted CAPACITY (not demand)','VERBATIM: "as of July 2025, the capacity value of these contracts is 47 GW (9.8 ESA + 7.1 CLOA + 30.1 ELOA)". ★★COMMITMENT LADDER: ESA (electric service agreement, firmest) 9.8 GW · CLOA (construction letter of authorization) 7.1 GW · ELOA (engineering letter of authorization - only site control + engineered site plan + $250k deposit, WEAKEST) 30.1 GW. So 64% of the headline sits at the weakest tier. ★DOMINION ITSELF WARNS AGAINST USING 47: "The Company is forecasting 16.6 GW of demand by 2046, not the 47 GW of capacity. This difference highlights the difference between capacity and demand." See the paired 16.6 GW row.','claude-opus-5 2026-07-28 (PDF fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Exelon (ComEd/PECO/BGE/Pepco)','IL/PA/MD/DC/NJ','PJM',18,'2026-02-12','https://www.sec.gov/Archives/edgar/data/1109357/000110935726000061/exc-20260506ex992.htm','Exelon 8-K exhibit 99.2 filed 2026-05-06 (EDGAR), footnote (2) and Customer-Focused slide','8-K earnings exhibit (SEC)','COMMITTED data-centre pipeline','VERBATIM: "Committed data center pipeline of ~18 GW (excludes 1 GW of other large load projects) with ~45% secured with TSAs as of Q4 2025 call (February 12, 2026)". ★COMMITMENT LADDER AGAIN: only ~45% is secured with Transmission Security Agreements — same pattern as Dominion (64% at the weakest ELOA tier) and Oncor (271 raw vs 122 forecast). ★Secondary coverage claims a further ~43 GW in study phases and ComEd +19 GW by 2030 — NOT inserted, not in this exhibit. ★NOTE this is the ONE utility whose figure IS in an SEC filing — but in an 8-K EXHIBIT 99.2 (the earnings deck), not the 10-K/10-Q. That is where to look for the rest.','claude-opus-5 2026-07-28 (EDGAR exhibit fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Dominion Energy Virginia','VA','PJM',16.6,'2026-01-06','https://www.pjm.com/-/media/DotCom/planning/res-adeq/load-forecast/dominion-documentation.pdf','Letter, Stan Blackwell (Director - Data Center Practice, Dominion Energy) to PJM Load Analysis Team, 2026-01-06, summary section','load-forecast submission to PJM','FORECAST DEMAND by 2046 (the citeable number)','VERBATIM: "The Company is forecasting 16.6 GW of demand by 2046, not the 47 GW of capacity." ★THIS is the demand figure Dominion stands behind; 47 GW is contracted capacity and is ~2.8x larger. Quote 16.6 for demand, 47 only as contracted capacity, and never interchangeably.','claude-opus-5 2026-07-28 (PDF fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Georgia Power (Southern Company)','GA','SERC/Southern',8.5,'2026-07-28','https://www.georgiapower.com/about/company/filings/irp.html','Georgia Power, Integrated Resource Plan page, "Supporting Georgia''s strong economic growth"','IRP (2025, approved)','TOTAL system load growth — NOT data-centre-specific','VERBATIM: "Over the next six years, we project approximately 8,500 megawatts (MW) of electrical load growth-an increase of approximately 2,600 MW by the end of 2030 when compared to projections in the 2023 IRP Update." ★★DO NOT LABEL THIS DATA-CENTRE LOAD: the page says ELECTRICAL LOAD GROWTH with no data-centre attribution anywhere (the only "data center" string on the page is a nav link). Secondary coverage (Utility Dive) reports 33 data-centre projects / 11,332 MW REMOVED from the pipeline and ~9,900 MW sought via All-Source RFP — NOT inserted, not verified against a primary filing. ★Georgia PSC now requires quarterly Large Load Economic Development Reports, which is the primary source to mine for a true DC-specific figure.','claude-opus-5 2026-07-28 (page fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ── Georgia Power / GA PSC Docket 55378 Q1-2026 Large Load Economic Development
-- Report (added 2026-07-28, batch 2). ★★ THE SINGLE BEST SOURCE FOUND: one filing
-- discloses EVERY rung of the ladder, so the 2-3x discount this table exists to
-- document is here provable end-to-end from one primary document:
--   73,100 MW pipeline -> 12,400 MW committed (executed RFS, 31 customers)
--   -> 8,500 MW broken ground -> 7,800 MW actual winter-2028/29 load  (9.4x).
-- ★ DC attribution is a COUNT share only: 101 of 122 attachment projects are
-- segment "Data Center/Crypto"; per-project MW is REDACTED, so no MW share exists.
-- ★★ 8.5 GW now appears TWICE for Georgia Power with unrelated meanings (8,448 MW
-- total system load growth vs 8,500 MW broken-ground large load). Coincidence, not
-- duplication -- see the collision warning in the 2026-03-31 row's notes.
-- ★ Found via the GA PSC FACTS document service, not EDGAR: Southern Co files no
-- slide deck on EDGAR (its 8-K ex99 is the press release, which carries no GW).
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Georgia Power (Southern Company)','GA','SERC/Southern',73.1,'2026-03-31','https://services.psc.ga.gov/api/v1/External/Public/Get/Document/DownloadFile/226607/107887','Georgia Power Company, Quarterly Large Load Economic Development Report Q1 2026, filed with the Georgia PSC 2026-05-15, Docket No. 55378 / 56002 (PUBLIC DISCLOSURE), section "Changes in the Economic Development Pipeline"','state-PUC quarterly report (GA PSC Docket 55378/56002)','PIPELINE of potential large-load projects (weakest rung)','VERBATIM: "As of March 31, 2026, the total pipeline of economic development projects through the mid-2030s has increased by 7,100 MW to 76,200 MW. Of this, 73,100 MW represents large load economic development projects." ★★THE FULL LADDER IN ONE FILING (this is the richest single source in the register - Georgia Power discloses every rung itself): 73,100 MW large-load pipeline -> 12,400 MW committed (executed RFS) -> 8,500 MW broken ground -> 7,800 MW actual near-term (winter 2028/29) load. Headline pipeline is 9.4x the near-term load it actually produces. Never quote 73.1 GW as demand. ★This is a PIPELINE (potential projects), NOT commitments and NOT demand - only 12,400 MW of it has an executed Request for Electric Service. ★Total pipeline incl. non-large-load is 76,200 MW; large-load moved 69,100 -> 76,200 via 12,600 MW entering, 2,900 MW exiting and a net -2,500 MW of resizing, so churn is large and this number is quarterly-volatile. ★DATA-CENTRE ATTRIBUTION (count, NOT MW): in the report''s project attachment 101 of 122 listed projects (83%) carry segment ''Data Center/Crypto''; the rest are Industrial 12, Manufacturing 7, Other 2. Per-project MW is REDACTED, so NO MW share can be derived and this row must NOT be restated as a data-centre-only MW figure. Georgia Power''s own definition (footnote 2): "Large load economic development projects represent those above the Company''s organic load growth thresholds for commercial and industrial load." [Doc page: https://psc.ga.gov/search/facts-document/?documentId=226607 ; filename ''DKT 55378 Lg Load Econ Dev Rept Q1 2026 PD.pdf''.] ','claude-opus-5 2026-07-28 (PDF fetched from GA PSC + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Georgia Power (Southern Company)','GA','SERC/Southern',23.6,'2026-03-31','https://services.psc.ga.gov/api/v1/External/Public/Get/Document/DownloadFile/226607/107887','Georgia Power Company, Quarterly Large Load Economic Development Report Q1 2026, filed with the Georgia PSC 2026-05-15, Docket No. 55378 / 56002 (PUBLIC DISCLOSURE), section "Changes in the Economic Development Pipeline", near-term paragraph','state-PUC quarterly report (GA PSC Docket 55378/56002)','PIPELINE, near-term subset (winter 2028/29)','VERBATIM: "For the near-term (winter of 2028/2029), the large load economic development pipeline has increased by 2,100 MW to 23,600 MW." ★The near-term slice of the 73,100 MW pipeline - still PIPELINE, not commitments. Compare with the 7,800 MW of near-term load from customers who have actually committed: 3.0x smaller. ★DATA-CENTRE ATTRIBUTION (count, NOT MW): in the report''s project attachment 101 of 122 listed projects (83%) carry segment ''Data Center/Crypto''; the rest are Industrial 12, Manufacturing 7, Other 2. Per-project MW is REDACTED, so NO MW share can be derived and this row must NOT be restated as a data-centre-only MW figure. Georgia Power''s own definition (footnote 2): "Large load economic development projects represent those above the Company''s organic load growth thresholds for commercial and industrial load." [Doc page: https://psc.ga.gov/search/facts-document/?documentId=226607 ; filename ''DKT 55378 Lg Load Econ Dev Rept Q1 2026 PD.pdf''.] ','claude-opus-5 2026-07-28 (PDF fetched from GA PSC + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Georgia Power (Southern Company)','GA','SERC/Southern',12.4,'2026-03-31','https://services.psc.ga.gov/api/v1/External/Public/Get/Document/DownloadFile/226607/107887','Georgia Power Company, Quarterly Large Load Economic Development Report Q1 2026, filed with the Georgia PSC 2026-05-15, Docket No. 55378 / 56002 (PUBLIC DISCLOSURE), section "Changes in Commitments from Large Load Customers"','state-PUC quarterly report (GA PSC Docket 55378/56002)','COMMITTED - executed Request for Electric Service, 31 customers','VERBATIM: "As of March 31, 2026, the portfolio of large load customers committed to receiving service from Georgia Power has grown by 500 MW, reaching a total of 12,400 MW across 31 customers. By the winter of 2028/2029, these customers will represent a load of 7,800 MW." ★★THIS IS THE FIRM RUNG: all 31 have executed an RFS (Request for Electric Service) or a Contract for Electric Service - the GA analogue of Dominion ESA/CLOA and Exelon TSAs. 12,400 MW is 17% of the 73,100 MW pipeline. ★Grew from 3,600 MW at the 2023 IRP Update to 12,400 MW (+8,800 MW) - VERBATIM: "Customer commitments expanded from 3,600 MW to 12,400 MW, representing an increase of 8,800 MW". ★Footnote 1 discloses a further 3,200 MW committed in April 2026 not in these values - note the COVER LETTER redacts that same number ("commitments added totaling REDACTED MW in April of 2026") while footnote 1 of the report prints it: 3,200 MW. ★DATA-CENTRE ATTRIBUTION (count, NOT MW): in the report''s project attachment 101 of 122 listed projects (83%) carry segment ''Data Center/Crypto''; the rest are Industrial 12, Manufacturing 7, Other 2. Per-project MW is REDACTED, so NO MW share can be derived and this row must NOT be restated as a data-centre-only MW figure. Georgia Power''s own definition (footnote 2): "Large load economic development projects represent those above the Company''s organic load growth thresholds for commercial and industrial load." [Doc page: https://psc.ga.gov/search/facts-document/?documentId=226607 ; filename ''DKT 55378 Lg Load Econ Dev Rept Q1 2026 PD.pdf''.] ','claude-opus-5 2026-07-28 (PDF fetched from GA PSC + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Georgia Power (Southern Company)','GA','SERC/Southern',8.5,'2026-03-31','https://services.psc.ga.gov/api/v1/External/Public/Get/Document/DownloadFile/226607/107887','Georgia Power Company, Quarterly Large Load Economic Development Report Q1 2026, filed with the Georgia PSC 2026-05-15, Docket No. 55378 / 56002 (PUBLIC DISCLOSURE), Introduction bullet 2 / Conclusion','state-PUC quarterly report (GA PSC Docket 55378/56002)','COMMITTED load that has BROKEN GROUND (construction started)','VERBATIM: "The amount of load that has broken ground continues to rise this quarter, now representing 8,500 MW out of 12,400 MW of customer commitments through the mid-2030s." ★The hardest evidence rung in the whole register: steel actually in the ground, 21 of the 31 committed projects, ten of them already online. 8,500 of 12,400 = 69% of commitments; 8,500 of 73,100 = 11.6% of the pipeline. ★★★NUMERIC COLLISION WARNING - DO NOT MERGE WITH THE OTHER GEORGIA POWER 8.5 GW ROW. The other row (as_of 2026-07-28, source georgiapower.com IRP page) is 8,448 MW of TOTAL SYSTEM load growth winters 2025/26 -> 2030/31, all customer classes. THIS row is 8,500 MW of large-load commitments under construction. The two figures are within 52 MW of each other by coincidence and mean entirely different things. Distinguish on as_of_date + request_type, never on the number. ★DATA-CENTRE ATTRIBUTION (count, NOT MW): in the report''s project attachment 101 of 122 listed projects (83%) carry segment ''Data Center/Crypto''; the rest are Industrial 12, Manufacturing 7, Other 2. Per-project MW is REDACTED, so NO MW share can be derived and this row must NOT be restated as a data-centre-only MW figure. Georgia Power''s own definition (footnote 2): "Large load economic development projects represent those above the Company''s organic load growth thresholds for commercial and industrial load." [Doc page: https://psc.ga.gov/search/facts-document/?documentId=226607 ; filename ''DKT 55378 Lg Load Econ Dev Rept Q1 2026 PD.pdf''.] ','claude-opus-5 2026-07-28 (PDF fetched from GA PSC + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Georgia Power (Southern Company)','GA','SERC/Southern',7.8,'2026-03-31','https://services.psc.ga.gov/api/v1/External/Public/Get/Document/DownloadFile/226607/107887','Georgia Power Company, Quarterly Large Load Economic Development Report Q1 2026, filed with the Georgia PSC 2026-05-15, Docket No. 55378 / 56002 (PUBLIC DISCLOSURE), Introduction bullet 1 / Conclusion','state-PUC quarterly report (GA PSC Docket 55378/56002)','FORECAST near-term load (winter 2028/29) from committed customers','VERBATIM: "By the winter of 2028/2029, these customers will represent a load of 7,800 MW." ★★THE NUMBER GEORGIA POWER ACTUALLY STANDS BEHIND near-term - the GA analogue of Dominion''s 16.6 GW. Against the 73,100 MW pipeline headline that is a 9.4x discount; against the 23,600 MW near-term pipeline, 3.0x. ★Of this 7,800 MW, VERBATIM: "projects that have broken ground now represent 6,800 MW of the total 7,800 MW of customer commitments for the winter of 2028/2029" - i.e. 87% is already under construction, so this rung is well-evidenced, unlike the pipeline. ★DATA-CENTRE ATTRIBUTION (count, NOT MW): in the report''s project attachment 101 of 122 listed projects (83%) carry segment ''Data Center/Crypto''; the rest are Industrial 12, Manufacturing 7, Other 2. Per-project MW is REDACTED, so NO MW share can be derived and this row must NOT be restated as a data-centre-only MW figure. Georgia Power''s own definition (footnote 2): "Large load economic development projects represent those above the Company''s organic load growth thresholds for commercial and industrial load." [Doc page: https://psc.ga.gov/search/facts-document/?documentId=226607 ; filename ''DKT 55378 Lg Load Econ Dev Rept Q1 2026 PD.pdf''.] ','claude-opus-5 2026-07-28 (PDF fetched from GA PSC + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
UPDATE utility_load_requests SET notes = notes || ' ★★CROSS-REF ADDED 2026-07-28: a SECOND Georgia Power row also reads 8.5 GW (as_of 2026-03-31) and is UNRELATED to this one - that one is 8,500 MW of large-load commitments that have BROKEN GROUND, from GA PSC Docket 55378 Q1-2026. THIS row is 8,448 MW of TOTAL SYSTEM load growth across all customer classes. Never merge or max() them. See also the 73.1/23.6/12.4/7.8 GW Georgia Power rows for the full commitment ladder.' WHERE utility = 'Georgia Power (Southern Company)' AND as_of_date = DATE '2026-07-28' AND gw_requested = 8.5;

-- ── Xcel Energy / AGA Financial Forum 2026 investor deck (added 2026-07-28, batch 2).
-- ★★ WIDEST DISCOUNT IN THE REGISTER: ~2 GW actually contracted against a ">20 GW"
-- pipeline (>10x). Slide 13 is a 3-tier funnel whose tiers are INCREMENTAL, not
-- nested: ~2 GW contracted/under construction + ~4 GW to be contracted by YE2027
-- (the slide's "~1 GW signed in 2026; Additional ~3 GW by end of 2027" proves the
-- increment) + ">20 GW Additional Pipeline" on top of those.
-- ★ The 20 GW row stores a FLOOR ("> 20 GW"), not a point estimate.
-- ★ Xcel files NO deck on EDGAR -- its 8-K ex99 is the earnings release, whose only
-- MW figures are GENERATION (1,900 MW Clean Energy Accelerator, 3,200 MW SPS RFP),
-- i.e. the "generation built FOR data centres is not data-centre load" trap again.
-- Deck found on the Xcel IR CDN (q4cdn) instead; as-of is the PDF CreationDate.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Xcel Energy (NSP-MN/NSP-WI/PSCo/SPS)','MN/WI/CO/TX/NM/ND/SD/MI','MISO/SPP',20,'2026-05-14','https://s202.q4cdn.com/586283047/files/doc_presentations/2026/05/XEL-Investor-Presentation-AGA-2026.pdf','Xcel Energy, "Making Energy Work Better" investor presentation, AGA Financial Forum 2026, slide 13 "DATA CENTER PIPELINE", top tier','investor presentation (AGA Financial Forum 2026)','PIPELINE - additional/uncontracted interest (FLOOR, slide says ''> 20 GW'')','VERBATIM: "DATA CENTER PIPELINE  > 20 GW  Additional Pipeline" with bullets "Hyperscalers and large developers", "Opportunities to upsize existing contracts", "Align with large load tariff filings". ★★VALUE IS A FLOOR: the slide says "> 20 GW", so 20 is stored as a lower bound, NOT a point estimate - never average or sum it. ★★READING TRAP: the >20 GW tier is labelled ''Additional Pipeline'' on the slide, i.e. ADDITIONAL TO the ~2 GW contracted and ~4 GW targeted - so total interest is >20 GW ON TOP OF ~6 GW, not >20 GW inclusive. Secondary coverage (Utility Dive, Seeking Alpha) restates it as ''>20 GW of active data center interest across the service territory'', i.e. inclusive. The slide''s own label is the citeable reading; the difference is ~6 GW. ★★SLIDE 13 IS A THREE-TIER FUNNEL AND THE TIERS ARE INCREMENTAL, NOT NESTED: ~2 GW ''Contracted / Under Construction'' + ~4 GW ''Contracted by Year End 2027'' + ''> 20 GW Additional Pipeline''. The ~4 GW is INCREMENTAL to the ~2 GW - proven by the slide''s own bullet "Expect ~1 GW signed in 2026; Additional ~3 GW by end of 2027" (1+3 = the ~4 GW tier), which is why secondary coverage says Xcel targets 6 GW of data centre load by YE2027 (2 already + 4 more). ★So contracted-today is ~2 GW against a >20 GW pipeline: a >10x discount, the widest in this register. ★AS-OF PROVENANCE: the deck prints NO as-of date. 2026-05-14 is taken from the PDF''s own CreationDate metadata (Thu May 14 08:57:49 2026 MST) plus its cover title ''AGA Financial Forum 2026''. Treat as deck date, not a measurement date.','claude-opus-5 2026-07-28 (PDF fetched from Xcel IR CDN + pdftotext -layout page 13 + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Xcel Energy (NSP-MN/NSP-WI/PSCo/SPS)','MN/WI/CO/TX/NM/ND/SD/MI','MISO/SPP',4,'2026-05-14','https://s202.q4cdn.com/586283047/files/doc_presentations/2026/05/XEL-Investor-Presentation-AGA-2026.pdf','Xcel Energy, "Making Energy Work Better" investor presentation, AGA Financial Forum 2026, slide 13 "DATA CENTER PIPELINE", middle tier','investor presentation (AGA Financial Forum 2026)','TARGET - incremental capacity Xcel aims to contract by YE2027','VERBATIM: "~4 GW Contracted by Year End 2027" with bullets "15+ year terms", "Total capacity ranging from 200 MW - 1+ GW", "Online by 2027 - 2030+ with ramps through mid 2030s", "Expect ~1 GW signed in 2026; Additional ~3 GW by end of 2027". ★★THIS IS A TARGET, NOT A COMMITMENT - it is capacity Xcel INTENDS to contract, so it is weaker evidence than Dominion ESA, Exelon TSA or Georgia Power RFS rows, which are executed. Do not file it under "committed". ★★SLIDE 13 IS A THREE-TIER FUNNEL AND THE TIERS ARE INCREMENTAL, NOT NESTED: ~2 GW ''Contracted / Under Construction'' + ~4 GW ''Contracted by Year End 2027'' + ''> 20 GW Additional Pipeline''. The ~4 GW is INCREMENTAL to the ~2 GW - proven by the slide''s own bullet "Expect ~1 GW signed in 2026; Additional ~3 GW by end of 2027" (1+3 = the ~4 GW tier), which is why secondary coverage says Xcel targets 6 GW of data centre load by YE2027 (2 already + 4 more). ★So contracted-today is ~2 GW against a >20 GW pipeline: a >10x discount, the widest in this register. ★AS-OF PROVENANCE: the deck prints NO as-of date. 2026-05-14 is taken from the PDF''s own CreationDate metadata (Thu May 14 08:57:49 2026 MST) plus its cover title ''AGA Financial Forum 2026''. Treat as deck date, not a measurement date.','claude-opus-5 2026-07-28 (PDF fetched from Xcel IR CDN + pdftotext -layout page 13 + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Xcel Energy (NSP-MN/NSP-WI/PSCo/SPS)','MN/WI/CO/TX/NM/ND/SD/MI','MISO/SPP',2,'2026-05-14','https://s202.q4cdn.com/586283047/files/doc_presentations/2026/05/XEL-Investor-Presentation-AGA-2026.pdf','Xcel Energy, "Making Energy Work Better" investor presentation, AGA Financial Forum 2026, slide 13 "DATA CENTER PIPELINE", bottom tier and its project table','investor presentation (AGA Financial Forum 2026)','CONTRACTED / UNDER CONSTRUCTION (firmest rung, itemised)','VERBATIM: "~2 GW Contracted / Under Construction", itemised on the slide as "200 MW / Online / 2035", "250 MW / Online / 2035", "200 MW / 2026 / 2028", "600 MW / 2026 / 2029" and one row shown as "*" with footnote "* Not publicly disclosed" (columns: Total Capacity, Planned Online, Full Ramp). ★★THE ONLY XCEL RUNG BACKED BY SIGNED CONTRACTS - 1,250 MW of it is disclosed project-by-project, the balance is withheld. ★Note the RAMP columns: two projects are already Online but do not reach Full Ramp until 2035, so contracted GW does NOT equal near-term load - the same capacity-vs-demand gap Dominion flags (47 vs 16.6). ★★SLIDE 13 IS A THREE-TIER FUNNEL AND THE TIERS ARE INCREMENTAL, NOT NESTED: ~2 GW ''Contracted / Under Construction'' + ~4 GW ''Contracted by Year End 2027'' + ''> 20 GW Additional Pipeline''. The ~4 GW is INCREMENTAL to the ~2 GW - proven by the slide''s own bullet "Expect ~1 GW signed in 2026; Additional ~3 GW by end of 2027" (1+3 = the ~4 GW tier), which is why secondary coverage says Xcel targets 6 GW of data centre load by YE2027 (2 already + 4 more). ★So contracted-today is ~2 GW against a >20 GW pipeline: a >10x discount, the widest in this register. ★AS-OF PROVENANCE: the deck prints NO as-of date. 2026-05-14 is taken from the PDF''s own CreationDate metadata (Thu May 14 08:57:49 2026 MST) plus its cover title ''AGA Financial Forum 2026''. Treat as deck date, not a measurement date.','claude-opus-5 2026-07-28 (PDF fetched from Xcel IR CDN + pdftotext -layout page 13 + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ── Duke Energy / Q1-2026 earnings deck (added 2026-07-28, batch 2).
-- ★★★ THIS ROW SET REVERSES TWO EARLIER "NO PRIMARY FIGURE" REJECTIONS OF DUKE.
-- Both rejections were correct about the channel checked (8-K/10-Q carry nothing:
-- the May-2026 8-K is routine, the July-2026 7.01 exhibits are NC rate-case
-- settlements) and wrong about the conclusion. Duke does not file its deck on
-- EDGAR; it sits on the IR CDN (s201.q4cdn.com). LESSON: "no primary figure" is a
-- verdict on the channels searched, not on the utility -- re-check the CDN deck.
-- ★★★ TIERS ARE NESTED HERE, NOT INCREMENTAL: "15.4 GW pipeline INCLUDES 7.6 GW
-- signed ESAs, OF WHICH 5 GW under construction". Xcel's funnel three rows above is
-- INCREMENTAL. Same graphic, opposite arithmetic -- read the connective words.
-- ★ Duke's deck also carries ~5 GW / ~14 GW / >7.5 GW / ~4.5 GW GENERATION figures.
-- The 5 GW generation number collides with the 5 GW under-construction load number.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Duke Energy (DEC/DEP/DEI/DEF/DEO/DEK)','NC/SC/IN/OH/KY/FL','non-ISO (Carolinas)/MISO/PJM',15.4,'2026-05-05','https://s201.q4cdn.com/583395453/files/doc_financials/2026/q1/Q1-2026-Earnings-Presentation-w-Reg-G.pdf','Duke Energy, Q1/2026 Earnings Review and Business Update (Harry Sideris / Brian Savoy, May 5, 2026), slide 10 "Delivering speed to power for large load customers"','investor presentation (Q1 2026 earnings deck)','PIPELINE - high-confidence late-stage (INCLUSIVE of the ESA and construction rungs)','VERBATIM: "~15.4 GW High-confidence, late-stage pipeline includes... ~7.6 GW signed ESAs underpinning accelerating load growth projections, of which... ~5 GW of data centers are under construction". ★★★NESTED, NOT INCREMENTAL - THE CRITICAL READING RULE FOR DUKE: slide 10''s own connective words make the tiers subsets of each other - "~15.4 GW High-confidence, late-stage pipeline INCLUDES... ~7.6 GW signed ESAs ... OF WHICH... ~5 GW of data centers are under construction". So 15.4 is the TOTAL and already contains 7.6, which already contains 5. DO NOT ADD THEM (15.4+7.6+5 = 28 GW is wrong). ★CONTRAST WITH XCEL IN THIS SAME REGISTER, WHERE THE TIERS ARE INCREMENTAL (~2 GW contracted PLUS ~4 GW target PLUS >20 GW additional pipeline). Two utilities, same funnel graphic, opposite arithmetic - always read the connective words, never assume. ★Even at Duke''s own "high-confidence, late-stage" framing the top rung is 3.1x the load actually under construction. ★★DUKE WAS REJECTED TWICE FROM THIS REGISTER on the basis of its 8-K filings (May-2026 8-K routine, zero data-centre mentions; July-2026 7.01 exhibits are NC rate-case settlements). The figures were never in an SEC filing - they are only in the IR deck, which Duke does NOT file on EDGAR. A "no primary figure" verdict is only ever a verdict on the channels checked.','claude-opus-5 2026-07-28 (deck fetched from Duke IR CDN + pdftotext -layout page 10 + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Duke Energy (DEC/DEP/DEI/DEF/DEO/DEK)','NC/SC/IN/OH/KY/FL','non-ISO (Carolinas)/MISO/PJM',7.6,'2026-05-05','https://s201.q4cdn.com/583395453/files/doc_financials/2026/q1/Q1-2026-Earnings-Presentation-w-Reg-G.pdf','Duke Energy, Q1/2026 Earnings Review and Business Update (May 5, 2026), slide 6 "Executing today, building for the future" and slide 9 "Converting large load prospects to projects"','investor presentation (Q1 2026 earnings deck)','SIGNED Electric Service Agreements (executed contracts)','VERBATIM (slide 6): "Signed additional ~2.7 GW of electric service agreements with data center customers", "~7.6 GW total data centers secured under ESAs", "~5 GW of data centers already under construction". VERBATIM (slide 9): "~7.6 GW Data Center ESAs (+~2.7 GW since Q4 call)". ★★THE FIRM RUNG: an ESA is an executed electric service agreement - the same instrument as Dominion''s firmest tier (ESA 9.8 GW), and stronger than Xcel''s "target to contract" or Georgia Power''s RFS. ★VELOCITY: +2.7 GW signed in a single quarter, 55% growth off ~4.9 GW at the Q4 call - the fastest contracting rate in this register. ★Slide 9 footnote (1): "Includes data center contract volume signed in 2024" - the 7.6 GW is CUMULATIVE since 2024, not a 2026 flow. ★★★NESTED, NOT INCREMENTAL - THE CRITICAL READING RULE FOR DUKE: slide 10''s own connective words make the tiers subsets of each other - "~15.4 GW High-confidence, late-stage pipeline INCLUDES... ~7.6 GW signed ESAs ... OF WHICH... ~5 GW of data centers are under construction". So 15.4 is the TOTAL and already contains 7.6, which already contains 5. DO NOT ADD THEM (15.4+7.6+5 = 28 GW is wrong). ★CONTRAST WITH XCEL IN THIS SAME REGISTER, WHERE THE TIERS ARE INCREMENTAL (~2 GW contracted PLUS ~4 GW target PLUS >20 GW additional pipeline). Two utilities, same funnel graphic, opposite arithmetic - always read the connective words, never assume.','claude-opus-5 2026-07-28 (deck fetched from Duke IR CDN + pdftotext -layout page 10 + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Duke Energy (DEC/DEP/DEI/DEF/DEO/DEK)','NC/SC/IN/OH/KY/FL','non-ISO (Carolinas)/MISO/PJM',5,'2026-05-05','https://s201.q4cdn.com/583395453/files/doc_financials/2026/q1/Q1-2026-Earnings-Presentation-w-Reg-G.pdf','Duke Energy, Q1/2026 Earnings Review and Business Update (Harry Sideris / Brian Savoy, May 5, 2026), slide 10 "Delivering speed to power for large load customers" (bottom tier) and slide 6','investor presentation (Q1 2026 earnings deck)','UNDER CONSTRUCTION (hardest rung)','VERBATIM: "~5 GW of data centers are under construction" (slide 10); "~5 GW of data centers already under construction" (slide 6). ★HARDEST EVIDENCE: steel in the ground, 66% of the 7.6 GW of signed ESAs and 32% of the 15.4 GW pipeline. Slide 10 names two of them - "Amazon data center site - Richmond County, NC" and "Substation to serve Microsoft data center - Catawba County, NC". ★DO NOT CONFUSE WITH DUKE''S GENERATION FIGURES IN THE SAME DECK: "~5 GW of gas generation" under construction and "EPC contracts signed for first ~5 GW of projects" are GENERATION BUILD, a different ~5 GW that happens to match. Duke also cites ~14 GW of capacity by 2031, >7.5 GW of new gas and ~4.5 GW of battery - all generation, none of it data-centre load. ★★★NESTED, NOT INCREMENTAL - THE CRITICAL READING RULE FOR DUKE: slide 10''s own connective words make the tiers subsets of each other - "~15.4 GW High-confidence, late-stage pipeline INCLUDES... ~7.6 GW signed ESAs ... OF WHICH... ~5 GW of data centers are under construction". So 15.4 is the TOTAL and already contains 7.6, which already contains 5. DO NOT ADD THEM (15.4+7.6+5 = 28 GW is wrong). ★CONTRAST WITH XCEL IN THIS SAME REGISTER, WHERE THE TIERS ARE INCREMENTAL (~2 GW contracted PLUS ~4 GW target PLUS >20 GW additional pipeline). Two utilities, same funnel graphic, opposite arithmetic - always read the connective words, never assume.','claude-opus-5 2026-07-28 (deck fetched from Duke IR CDN + pdftotext -layout page 10 + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ── PPL / Investor Meetings May 2026 deck (added 2026-07-28, batch 2), split into
-- PPL Electric Utilities (PA/PJM) and LG&E-KU (KY), which have separate ladders.
-- ★★★ REVERSES PPL'S EARLIER DOUBLE-REJECTION, AND EXPLAINS IT. PPL was rejected for
-- "4 conflicting figures in coverage (60 / 28.3 / 20.7 / 14.4 GW)". Slide 16 shows
-- they were never four metrics: it is ONE bar chart, "PPL Electric Utilities Signed
-- Data Center Agreements (in GW)", printed per quarter -- ~3, ~5, 8.3, 8.6, 10.9,
-- 14.4, 20.5, 25.2, 28.3 from Q1'24 to Q1'26. Coverage was quoting different
-- QUARTERS of one series as if they were rival statistics.
-- ★ LESSON: conflicting secondary numbers are often one time series sampled at
-- different dates. Find the chart before concluding the sources disagree.
-- ★★ KY holds the steepest discount in the register: 11.9 GW data-centre queue ->
-- ~4 GW "highly active" -> ~650 MW under construction or agreement (18.3x).
-- ★★ PPL's footnote (1) is the key qualification on 28.3 GW: the agreements are with
-- DEVELOPERS and their costs are REIMBURSABLE if they walk.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('PPL Electric Utilities (PA)','PA','PJM',28.3,'2026-03-31','https://investors.pplweb.com/download/PPL+Investor+Meetings_May+2026_FINAL.pdf','PPL Corporation, "Investor Meetings May 2026", slide 16 "PA Economic Development Powered by Data Centers"','investor presentation (PPL Investor Meetings, May 2026)','SIGNED AGREEMENTS WITH DEVELOPERS - ''advanced stages'' (developer may walk)','VERBATIM: "Data centers with signed agreements have increased to 28.3GW (up from 25.2GW in Q4), a 12% increase". ★★★THE QUALIFICATION THAT GUTS THE 28.3 GW HEADLINE - PPL''s own footnote (1), VERBATIM: "The data centers in advanced stages represent projects that have signed agreements with developers and costs being incurred are reimbursable by the developers if they do not move forward with the projects." So these are agreements with DEVELOPERS, not end users, and the developer may WALK AWAY - the reimbursement clause exists precisely because PPL expects some to. This is PPL''s analogue of Dominion''s $250k-deposit ELOA tier. ★TRAJECTORY (same chart, verbatim series): ~3, ~5, 8.3, 8.6, 10.9, 14.4, 20.5, 25.2, 28.3 GW across Q1''24 to Q1''26 - 9.4x in eight quarters. ★★★THIS ROW SET RESOLVES PPL''S EARLIER DOUBLE-REJECTION. PPL was rejected twice for ''4 conflicting figures in coverage (60 GW queue / 28.3 advanced / 20.7 by 2030 / 14.4 signed by 2034)''. Slide 16 shows they were never 4 metrics: its bar chart is ONE series, ''PPL Electric Utilities Signed Data Center Agreements (in GW)'', printed quarter by quarter - ~3 (Q1''24), ~5, 8.3, 8.6, 10.9, 14.4 (Q2''25), 20.5, 25.2 (Q4''25), 28.3 (Q1''26). The ''14.4'' in coverage is simply the Q2-2025 point of the same series being quoted as a separate statistic. ★LESSON: conflicting secondary figures are often ONE time series sampled at different dates - find the chart before concluding the sources disagree.','claude-opus-5 2026-07-28 (deck fetched from investors.pplweb.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('PPL Electric Utilities (PA)','PA','PJM',10,'2026-03-31','https://investors.pplweb.com/download/PPL+Investor+Meetings_May+2026_FINAL.pdf','PPL Corporation, "Investor Meetings May 2026", slide 16 "PA Economic Development Powered by Data Centers" and slide 20','investor presentation (PPL Investor Meetings, May 2026)','UNDER Electric Service Agreements (executed, ~80% take-or-pay)','VERBATIM: "~10GW under ESAs with 5GW under construction" (slide 16); "~10GW under Electric Service Agreements (ESAs) with 5GW under construction" (slide 20). ★★THE FIRM RUNG, and PPL discloses the teeth - VERBATIM: "Our Electric Service Agreements (ESAs) help protect our other utility customers by requiring data center customers to pay approximately 80% of anticipated load, even if they use less electricity, until the costs incurred to extend service are fully recovered." An ~80% take-or-pay floor makes this materially firmer than the 28.3 GW developer-agreement tier. ★Only 35% of the 28.3 GW headline has reached an ESA.','claude-opus-5 2026-07-28 (deck fetched from investors.pplweb.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('PPL Electric Utilities (PA)','PA','PJM',5,'2026-03-31','https://investors.pplweb.com/download/PPL+Investor+Meetings_May+2026_FINAL.pdf','PPL Corporation, "Investor Meetings May 2026", slide 16 "PA Economic Development Powered by Data Centers" and slide 20','investor presentation (PPL Investor Meetings, May 2026)','UNDER CONSTRUCTION (hardest rung)','VERBATIM: "~10GW under ESAs with 5GW under construction". ★HARDEST EVIDENCE: 5 GW of the 28.3 GW headline is actually being built - a 5.7x discount from headline to steel. ★Compare across this register at the same rung: PPL PA 28.3 -> 5 (5.7x), Duke 15.4 -> 5 (3.1x), Georgia Power 73.1 -> 8.5 (8.6x). ★★★THE QUALIFICATION THAT GUTS THE 28.3 GW HEADLINE - PPL''s own footnote (1), VERBATIM: "The data centers in advanced stages represent projects that have signed agreements with developers and costs being incurred are reimbursable by the developers if they do not move forward with the projects." So these are agreements with DEVELOPERS, not end users, and the developer may WALK AWAY - the reimbursement clause exists precisely because PPL expects some to. This is PPL''s analogue of Dominion''s $250k-deposit ELOA tier.','claude-opus-5 2026-07-28 (deck fetched from investors.pplweb.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('LG&E and KU (PPL, KY)','KY','non-ISO (LG&E-KU BA, SERC)',11.9,'2026-03-31','https://investors.pplweb.com/download/PPL+Investor+Meetings_May+2026_FINAL.pdf','PPL Corporation, "Investor Meetings May 2026", slide 17 "KY Economic Development Update"','investor presentation (PPL Investor Meetings, May 2026)','ECONOMIC-DEVELOPMENT QUEUE, data-centre-related (weakest rung)','VERBATIM: "Economic development queue in KY shows total potential load growth of 12.9GW through 2032" and "Data center related load exceeds 11.9GW (up from 8.2GW in previous update); about 4GW are considered highly active, of which ~650MW is under construction or agreement". ★★NOTE THE WORD "POTENTIAL" - this is a QUEUE of requests, not commitments. ★Of the 12.9 GW total queue, 11.9 GW is data-centre and 1 GW non-data-centre, so KY is 92% data centre by MW (unlike Georgia Power, where only a project COUNT share is knowable). ★★THE STEEPEST DISCOUNT IN THE ENTIRE REGISTER: 11.9 GW queued -> ~4 GW highly active -> ~0.65 GW under construction or agreement = 18.3x from queue to firm.','claude-opus-5 2026-07-28 (deck fetched from investors.pplweb.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('LG&E and KU (PPL, KY)','KY','non-ISO (LG&E-KU BA, SERC)',4,'2026-03-31','https://investors.pplweb.com/download/PPL+Investor+Meetings_May+2026_FINAL.pdf','PPL Corporation, "Investor Meetings May 2026", slide 17 "KY Economic Development Update"','investor presentation (PPL Investor Meetings, May 2026)','QUEUE subset PPL calls ''highly active''','VERBATIM: "about 4GW are considered highly active, of which ~650MW is under construction or agreement". ★An intermediate rung with no contractual meaning - "highly active" is PPL''s own judgement of engagement, NOT an executed instrument. Treat as softer than any ESA/RFS/TSA row in this register. ★34% of the 11.9 GW data-centre queue.','claude-opus-5 2026-07-28 (deck fetched from investors.pplweb.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('LG&E and KU (PPL, KY)','KY','non-ISO (LG&E-KU BA, SERC)',0.65,'2026-03-31','https://investors.pplweb.com/download/PPL+Investor+Meetings_May+2026_FINAL.pdf','PPL Corporation, "Investor Meetings May 2026", slide 17 "KY Economic Development Update"','investor presentation (PPL Investor Meetings, May 2026)','UNDER CONSTRUCTION OR AGREEMENT (hardest rung)','VERBATIM: "about 4GW are considered highly active, of which ~650MW is under construction or agreement". ★★THE PUNCHLINE OF THE WHOLE REGISTER: Kentucky''s data-centre queue is 11.9 GW and the part that is actually under construction or contract is 650 MW - 5.5% of it, an 18.3x discount. Anyone quoting "11.9 GW of data centre demand in Kentucky" is overstating the firm number by more than an order of magnitude, and PPL says so on the same slide. ★Smallest value in the register - do not mistake the units (0.65 GW = 650 MW).','claude-opus-5 2026-07-28 (deck fetched from investors.pplweb.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('LG&E and KU (PPL, KY)','KY','non-ISO (LG&E-KU BA, SERC)',3.5,'2026-03-31','https://investors.pplweb.com/download/PPL+Investor+Meetings_May+2026_FINAL.pdf','PPL Corporation, "Investor Meetings May 2026", slide 17 "KY Economic Development Update"','investor presentation (PPL Investor Meetings, May 2026)','FORECAST total expected new load by 2032 - NOT data-centre-specific','VERBATIM: "Updated projections indicate ~3.5GW of expected new load by 2032 (increase from ~1.8GW in CPCN forecast)". ★★THE NUMBER PPL ACTUALLY PLANS TO - the KY analogue of Dominion''s 16.6 GW. Against the 12.9 GW total queue that is a 3.7x discount. ★★DO NOT LABEL THIS DATA-CENTRE LOAD: the slide says "expected new load", covering both the 11.9 GW data-centre and 1 GW non-data-centre queues - same error class as the Georgia Power 8.5 GW row. ★It nearly DOUBLED against the 2025 CPCN filing assumption of ~1.8 GW, and PPL says it "could need to file a CPCN for additional generation resources as early as this year".','claude-opus-5 2026-07-28 (deck fetched from investors.pplweb.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ── Entergy / 2026 Investor Day deck, June 9 2026 (added 2026-07-28, batch 2).
-- ★★ REVERSES ENTERGY'S EARLIER REJECTION WITHOUT INVALIDATING IT: the rejection was
-- that Entergy's Meta/LPSC release states GENERATION built for the data centre and
-- never the data centre's LOAD. Still true, and its Q1-2026 release carries no load
-- GW either. The number exists only in the Investor Day deck.
-- ★★ STORED AS TWO BOUND ROWS (7 and 12), not a midpoint -- Entergy publishes a RANGE
-- (~7-12 GW data centres, ~3-5 GW other industries, ~10-17 GW total) and averaging it
-- would invent a precision the source does not have.
-- ★★ These are "Potential additions to base case" -- upside EXPLICITLY EXCLUDED from
-- Entergy's forecast. Never compare with, or sum into, a forecast-demand row.
-- ★ DISCLOSURE GAP WORTH NOTING: Entergy prints the funnel STAGES (Potential customer
-- -> Reimbursement agreement -> Project study -> FID -> ESA -> Customer) but attaches
-- NO GW to any stage, so its firm rung is unquantified -- unlike Duke, PPL and
-- Georgia Power. Its only ESA figure is monetary ($7B of customer savings).
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Entergy (E-LA/E-AR/E-MS/E-TX)','LA/AR/MS/TX','MISO',7,'2026-06-09','https://s201.q4cdn.com/714390239/files/doc_presentations/2026/Jun/09/Entergy-2026-Investor-Day.pdf','Entergy, 2026 Investor Day (June 9, 2026), slide "Strong pipeline for sales growth opportunities / Customer interest continues to expand", "Potential additions to base case" chart (data centres, LOW bound)','investor presentation (Entergy 2026 Investor Day)','PIPELINE range LOW bound - potential additions to base case (not forecast)','VERBATIM: the chart "Potential additions to base case" shows "Data centers ~7-12 GW", "Other industries ~3-5 GW", "Total ~10-17 GW". This row is the LOW bound of the data-centre range. ★★CRITICAL SEMANTIC - THIS IS EXPLICITLY *NOT* IN ENTERGY''S FORECAST. The chart is headed "Potential additions to base case", i.e. upside EXCLUDED from the base plan. It is the opposite of a forecast row like Dominion''s 16.6 GW or Oncor''s 122 GW, and must never be compared with one or summed into a demand total. ★RANGE, NOT A POINT: Entergy publishes ~7-12 GW for data centres and ~3-5 GW for other industries, totalling ~10-17 GW. Both bounds are stored as separate rows so neither the low nor the high end can be quietly dropped; do NOT average them into a single ''9.5 GW''. ★★ENTERGY SHOWS THE LADDER''S SHAPE BUT WITHHOLDS ITS RUNGS - worth recording as a disclosure gap. The same slide prints the full pipeline funnel as named stages: "Potential customer" -> "Reimbursement agreement" -> "Project study" -> "FID" -> "ESA" -> "Customer", annotated "Increasing probability in forecast" - but attaches NO GW to any individual stage. So unlike Duke (15.4/7.6/5), PPL (28.3/10/5) and Georgia Power (73.1/12.4/8.5/7.8), Entergy''s firm rung is NOT publicly quantified. The only ESA-related figure in the whole deck is monetary, VERBATIM: "With ESAs to date, we expect $7 billion in customer savings" (slide 9, ''Fair Share Plus pledge''), with no GW attached. ★★THIS REVERSES ENTERGY''S EARLIER REJECTION, AND THE REJECTION WAS STILL RIGHT: Entergy was rejected because its LPSC/Meta release states the GENERATION it will build (3 CCGTs, 1,500 MW solar, transmission) but never Meta''s LOAD. That remains true - and its Q1-2026 earnings release (checked 2026-07-28) also carries no load GW, only "a 14.9 percent increase in industrial volume driven by higher sales to data center, primary metals, and transportation customers". The figure exists only in the Investor Day deck.','claude-opus-5 2026-07-28 (Investor Day deck fetched from Entergy IR CDN + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Entergy (E-LA/E-AR/E-MS/E-TX)','LA/AR/MS/TX','MISO',12,'2026-06-09','https://s201.q4cdn.com/714390239/files/doc_presentations/2026/Jun/09/Entergy-2026-Investor-Day.pdf','Entergy, 2026 Investor Day (June 9, 2026), slide "Strong pipeline for sales growth opportunities / Customer interest continues to expand", "Potential additions to base case" chart (data centres, HIGH bound)','investor presentation (Entergy 2026 Investor Day)','PIPELINE range HIGH bound - potential additions to base case (not forecast)','VERBATIM: the chart "Potential additions to base case" shows "Data centers ~7-12 GW", "Other industries ~3-5 GW", "Total ~10-17 GW". This row is the HIGH bound of the data-centre range. ★★CRITICAL SEMANTIC - THIS IS EXPLICITLY *NOT* IN ENTERGY''S FORECAST. The chart is headed "Potential additions to base case", i.e. upside EXCLUDED from the base plan. It is the opposite of a forecast row like Dominion''s 16.6 GW or Oncor''s 122 GW, and must never be compared with one or summed into a demand total. ★RANGE, NOT A POINT: Entergy publishes ~7-12 GW for data centres and ~3-5 GW for other industries, totalling ~10-17 GW. Both bounds are stored as separate rows so neither the low nor the high end can be quietly dropped; do NOT average them into a single ''9.5 GW''. ★★ENTERGY SHOWS THE LADDER''S SHAPE BUT WITHHOLDS ITS RUNGS - worth recording as a disclosure gap. The same slide prints the full pipeline funnel as named stages: "Potential customer" -> "Reimbursement agreement" -> "Project study" -> "FID" -> "ESA" -> "Customer", annotated "Increasing probability in forecast" - but attaches NO GW to any individual stage. So unlike Duke (15.4/7.6/5), PPL (28.3/10/5) and Georgia Power (73.1/12.4/8.5/7.8), Entergy''s firm rung is NOT publicly quantified. The only ESA-related figure in the whole deck is monetary, VERBATIM: "With ESAs to date, we expect $7 billion in customer savings" (slide 9, ''Fair Share Plus pledge''), with no GW attached. ★★THIS REVERSES ENTERGY''S EARLIER REJECTION, AND THE REJECTION WAS STILL RIGHT: Entergy was rejected because its LPSC/Meta release states the GENERATION it will build (3 CCGTs, 1,500 MW solar, transmission) but never Meta''s LOAD. That remains true - and its Q1-2026 earnings release (checked 2026-07-28) also carries no load GW, only "a 14.9 percent increase in industrial volume driven by higher sales to data center, primary metals, and transportation customers". The figure exists only in the Investor Day deck.','claude-opus-5 2026-07-28 (Investor Day deck fetched from Entergy IR CDN + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ── Arizona Public Service / Pinnacle West May-2026 investor deck (added 2026-07-28,
-- batch 2). ★ NOTE THE CHANNEL: Pinnacle West is the one utility here that FURNISHES
-- ITS INVESTOR DECK ON EDGAR (8-K item 7.01, "mayinvestordeck.htm"), so no CDN hunt
-- was needed -- worth checking first for any remaining utility.
-- ★★ APS frames the ladder against its OWN SYSTEM PEAK, which no other filer in this
-- table does: 8.6 GW 2025 system peak / 4.5 GW committed / ~20 GW uncommitted. The
-- committed large load alone is 52% of the entire existing system peak.
-- ★ The 8.6 GW system peak is deliberately NOT a row: it is existing demand, not a
-- load request, and storing it would corrupt what gw_requested means.
-- ★★ NOT DATA-CENTRE-ATTRIBUTED. The slide says "additional load"; it never says data
-- centre. Labelled accordingly, same as the Georgia Power 8,448 MW row.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Arizona Public Service (Pinnacle West)','AZ','non-ISO (WECC/AZPS BA)',4.5,'2026-05-06','https://www.sec.gov/Archives/edgar/data/764622/000076462226000029/mayinvestordeck.htm','Pinnacle West Capital Corp, May 2026 investor deck furnished as an exhibit to its 8-K of 2026-05-06 (EDGAR), slide 13 "Significant investment opportunity to serve increased demand", ''Committed Load'' figure','8-K item 7.01 investor deck (SEC)','COMMITTED large load (firm rung; NOT stated to be data-centre)','VERBATIM: "8.6GW 2025 System Peak  4.5GW Committed Load  ~20GW Uncommitted Load Opportunity", under the heading "Significant investment opportunity to serve increased demand / There is significant additional load we need to be ready to serve". ★★THE DENOMINATOR IS THE POINT, AND IT IS APS''S OWN SLIDE: the same three figures read "8.6GW 2025 System Peak / 4.5GW Committed Load / ~20GW Uncommitted Load Opportunity". So APS''s COMMITTED large load alone is 52% of its entire existing system peak, and the uncommitted opportunity is 2.3x the whole system. ★The 8.6 GW system peak is deliberately NOT stored as its own row - it is existing peak demand, not a load request, and adding it would corrupt the register''s semantics. ★★DO NOT LABEL THIS DATA-CENTRE LOAD. The slide says only "additional load we need to be ready to serve" - "Committed Load" and "Uncommitted Load Opportunity" carry NO data-centre attribution anywhere on it. Arizona growth is widely reported as data-centre driven, but APS does not say so here. Same discipline as the Georgia Power 8,448 MW row. ★APS does not disclose what instrument "committed" means - unlike Dominion (ESA/CLOA/ELOA), Exelon (TSA), Duke (ESA), PPL (ESA) or Georgia Power (RFS) - so this rung is less well-evidenced than those despite the confident label. ★The slide''s own cited source is the "APS 2026-2035 Ten Year Transmission System Plan" (filed with the ACC 2026-01-30, docket E-99999A-25-0006) - that plan is the deeper primary to mine next. ★Related open ACC dockets named on the deck: "Inquiry into Data Center Rate Classifications" E-00000A-25-0069 and an ACC Large Load Users Development Workshop held 2026-04-16; APS''s 2026 IRP was due to be filed 2026-08-03 and should carry a data-centre-attributed figure.','claude-opus-5 2026-07-28 (EDGAR exhibit fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Arizona Public Service (Pinnacle West)','AZ','non-ISO (WECC/AZPS BA)',20,'2026-05-06','https://www.sec.gov/Archives/edgar/data/764622/000076462226000029/mayinvestordeck.htm','Pinnacle West Capital Corp, May 2026 investor deck furnished as an exhibit to its 8-K of 2026-05-06 (EDGAR), slide 13 "Significant investment opportunity to serve increased demand", ''Uncommitted Load Opportunity'' figure','8-K item 7.01 investor deck (SEC)','UNCOMMITTED load opportunity (weakest rung; approx, NOT data-centre-specific)','VERBATIM: "8.6GW 2025 System Peak  4.5GW Committed Load  ~20GW Uncommitted Load Opportunity". ★★THE WORD IS "OPPORTUNITY", NOT REQUESTS: this is APS''s own commercial assessment of addressable load, weaker even than an interconnection queue (Oncor 271 GW) because no one has necessarily applied. Treat as the softest class of number in this register. ★4.4x the committed figure. ★★THE DENOMINATOR IS THE POINT, AND IT IS APS''S OWN SLIDE: the same three figures read "8.6GW 2025 System Peak / 4.5GW Committed Load / ~20GW Uncommitted Load Opportunity". So APS''s COMMITTED large load alone is 52% of its entire existing system peak, and the uncommitted opportunity is 2.3x the whole system. ★The 8.6 GW system peak is deliberately NOT stored as its own row - it is existing peak demand, not a load request, and adding it would corrupt the register''s semantics. ★★DO NOT LABEL THIS DATA-CENTRE LOAD. The slide says only "additional load we need to be ready to serve" - "Committed Load" and "Uncommitted Load Opportunity" carry NO data-centre attribution anywhere on it. Arizona growth is widely reported as data-centre driven, but APS does not say so here. Same discipline as the Georgia Power 8,448 MW row. ★The slide''s own cited source is the "APS 2026-2035 Ten Year Transmission System Plan" (filed with the ACC 2026-01-30, docket E-99999A-25-0006) - that plan is the deeper primary to mine next. ★Related open ACC dockets named on the deck: "Inquiry into Data Center Rate Classifications" E-00000A-25-0069 and an ACC Large Load Users Development Workshop held 2026-04-16; APS''s 2026 IRP was due to be filed 2026-08-03 and should carry a data-centre-attributed figure.','claude-opus-5 2026-07-28 (EDGAR exhibit fetched + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ── NV Energy / 2026 Joint IRP, PUCN Docket 26-05, Volume 6 of 41 (added 2026-07-28,
-- batch 2).
-- ★★★ THE SINGLE MOST VALUABLE FINDING FOR THIS TABLE: NV Energy PUBLISHES ITS OWN
-- HAIRCUT, TIERED BY COMMITMENT STAGE -- "The loads of projects in the study phase saw
-- an average overall reduction of 83 percent; the loads of projects with signed Rule 9
-- agreements were reduced by 38 percent" (footnote 7: ~43% excluding one LOI customer
-- carried at 100%). Every other row in this register DEMONSTRATES the headline-vs-
-- forecast gap; this one supplies the multiplier, from the filer, in a regulatory
-- filing. Study-phase requests are worth ~17% of face value; signed ~57-62%.
-- ★★ THE 6 GW IS NOT A SUPPLY COMMITMENT: Rule 9 agreements are infrastructure-only
-- and NV Energy says so -- "These agreements do not address generation and electric
-- supply." Do not rank it alongside Duke/PPL/Dominion ESAs.
-- ★ Data-centre share here is by MW (16,530 of 16,930 = 97.6%), not by project count
-- as at Georgia Power -- the cleanest DC-attributed request total in the table.
-- ★ Channel: state-PUC IRP, same channel that produced the Georgia Power rows. For
-- utilities that file no deck on EDGAR, the state commission is the reliable route.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('NV Energy (Nevada Power + Sierra Pacific)','NV','non-ISO (WECC; NVE BA)',22,'2026-05-06','https://www.nvenergy.com/publish/content/dam/nvenergy/brochures_arch/about-nvenergy/rates-regulatory/recent-regulatory-filings/2026-irp/NPC-SPPC-Volume-6.pdf','Nevada Power Company and Sierra Pacific Power Company (both d/b/a NV Energy), Joint Application for approval of their 2027-2046 Integrated Resource Plan, Docket No. 26-05, Volume 6 of 41 (Summary), before the Public Utilities Commission of Nevada, Section I Executive Summary','state-PUC Integrated Resource Plan (PUCN Docket 26-05, 2026 Joint IRP)','INTEREST INQUIRIES from data centres (weakest rung - informal, pre-application)','VERBATIM: "NV Energy has received approximately 22,000 megawatts ("MW") or 22 gigawatts ("GW") of interest inquiries from data centers and has executed approximately 6 GW of signed Rule 9 agreements ... to facilitate the transmission, substation, and high voltage distribution infrastructure needed to interconnect these large loads. These agreements do not address generation and electric supply." ★★"INTEREST INQUIRIES" IS THE SOFTEST CATEGORY IN THIS REGISTER - softer than an interconnection queue (Oncor 271 GW), because no application need have been filed. ★★★THE MOST IMPORTANT SENTENCE IN THIS ENTIRE REGISTER - A UTILITY PUBLISHING ITS OWN HAIRCUT, TIERED BY COMMITMENT LEVEL. VERBATIM: "Consistent with past practice, these requests are scaled down in the retail load forecast. The loads of projects in the study phase saw an average overall reduction of 83 percent; the loads of projects with signed Rule 9 agreements were reduced by 38 percent." Footnote 7 refines it, VERBATIM: "The adjustment percentages will vary by individual project and year. The overall percentages include one customer who signed a letter of intent and is included at 100 percent of their request. Excluding this customer, the overall average reduction percentage for projects with a signed agreement is approximately 43 percent in this load forecast update." ★★SO THE DISCOUNT CURVE IS NOW EMPIRICAL, NOT INFERRED: study-phase requests are worth ~17% of face value and signed-agreement requests ~57-62%. Every other row in this table shows the gap between headline and forecast; NV Energy prints the multiplier itself. ★AS-OF PROVENANCE: the volume prints no filing date on its face (docket shown as "Docket No. 26-05___", number not yet assigned). 2026-05-06 is the PDF CreationDate; the latest date referenced inside the document is 2026-04-30.','claude-opus-5 2026-07-28 (PUCN IRP volume fetched from nvenergy.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('NV Energy (Nevada Power + Sierra Pacific)','NV','non-ISO (WECC; NVE BA)',16.93,'2026-05-06','https://www.nvenergy.com/publish/content/dam/nvenergy/brochures_arch/about-nvenergy/rates-regulatory/recent-regulatory-filings/2026-irp/NPC-SPPC-Volume-6.pdf','Nevada Power Company and Sierra Pacific Power Company (both d/b/a NV Energy), Joint Application for approval of their 2027-2046 Integrated Resource Plan, Docket No. 26-05, Volume 6 of 41 (Summary), before the Public Utilities Commission of Nevada, Section III Forecast of Growth, ''Large customer assumptions''','state-PUC Integrated Resource Plan (PUCN Docket 26-05, 2026 Joint IRP)','REQUESTED capacity additions, all 50 bundled-service large-load projects','VERBATIM: "Large load customer growth in the 2026 Joint IRP Forecast reflects the continued unprecedented load growth expected from 50 bundled-service projects considered for this forecast. These projects are located primarily within the TRIC area at Sierra and the Apex area at Nevada Power. In total, these customers requested approximately 16,930 MW of capacity additions, with 11,710 MW at Sierra and 5,220 MW at Nevada Power." ★This is ALL large load (data centre and not); see the paired 16.53 GW row for the data-centre-only figure. ★DATA-CENTRE SHARE BY MW, NOT BY COUNT: 16,530 of 16,930 MW = 97.6% of the requested large load is data centre - 39 of the 50 bundled-service projects. Contrast Georgia Power, where per-project MW is redacted and only a project-COUNT share (101/122) is knowable. ★★★THE MOST IMPORTANT SENTENCE IN THIS ENTIRE REGISTER - A UTILITY PUBLISHING ITS OWN HAIRCUT, TIERED BY COMMITMENT LEVEL. VERBATIM: "Consistent with past practice, these requests are scaled down in the retail load forecast. The loads of projects in the study phase saw an average overall reduction of 83 percent; the loads of projects with signed Rule 9 agreements were reduced by 38 percent." Footnote 7 refines it, VERBATIM: "The adjustment percentages will vary by individual project and year. The overall percentages include one customer who signed a letter of intent and is included at 100 percent of their request. Excluding this customer, the overall average reduction percentage for projects with a signed agreement is approximately 43 percent in this load forecast update." ★★SO THE DISCOUNT CURVE IS NOW EMPIRICAL, NOT INFERRED: study-phase requests are worth ~17% of face value and signed-agreement requests ~57-62%. Every other row in this table shows the gap between headline and forecast; NV Energy prints the multiplier itself. ★AS-OF PROVENANCE: the volume prints no filing date on its face (docket shown as "Docket No. 26-05___", number not yet assigned). 2026-05-06 is the PDF CreationDate; the latest date referenced inside the document is 2026-04-30.','claude-opus-5 2026-07-28 (PUCN IRP volume fetched from nvenergy.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('NV Energy (Nevada Power + Sierra Pacific)','NV','non-ISO (WECC; NVE BA)',16.53,'2026-05-06','https://www.nvenergy.com/publish/content/dam/nvenergy/brochures_arch/about-nvenergy/rates-regulatory/recent-regulatory-filings/2026-irp/NPC-SPPC-Volume-6.pdf','Nevada Power Company and Sierra Pacific Power Company (both d/b/a NV Energy), Joint Application for approval of their 2027-2046 Integrated Resource Plan, Docket No. 26-05, Volume 6 of 41 (Summary), before the Public Utilities Commission of Nevada, Section III Forecast of Growth, ''Large customer assumptions''','state-PUC Integrated Resource Plan (PUCN Docket 26-05, 2026 Joint IRP)','REQUESTED capacity+energy, the 39 DATA-CENTRE projects only','VERBATIM: "Thirty-nine of these projects are bundled-service high load factor data centers that have requested 16,530 MW of capacity and energy alone." ★★THE CLEANEST DATA-CENTRE-SPECIFIC REQUEST FIGURE IN THE REGISTER - a regulator-filed MW total attributable to data centres by name, not inferred from a share. ★DATA-CENTRE SHARE BY MW, NOT BY COUNT: 16,530 of 16,930 MW = 97.6% of the requested large load is data centre - 39 of the 50 bundled-service projects. Contrast Georgia Power, where per-project MW is redacted and only a project-COUNT share (101/122) is knowable. ★★★THE MOST IMPORTANT SENTENCE IN THIS ENTIRE REGISTER - A UTILITY PUBLISHING ITS OWN HAIRCUT, TIERED BY COMMITMENT LEVEL. VERBATIM: "Consistent with past practice, these requests are scaled down in the retail load forecast. The loads of projects in the study phase saw an average overall reduction of 83 percent; the loads of projects with signed Rule 9 agreements were reduced by 38 percent." Footnote 7 refines it, VERBATIM: "The adjustment percentages will vary by individual project and year. The overall percentages include one customer who signed a letter of intent and is included at 100 percent of their request. Excluding this customer, the overall average reduction percentage for projects with a signed agreement is approximately 43 percent in this load forecast update." ★★SO THE DISCOUNT CURVE IS NOW EMPIRICAL, NOT INFERRED: study-phase requests are worth ~17% of face value and signed-agreement requests ~57-62%. Every other row in this table shows the gap between headline and forecast; NV Energy prints the multiplier itself. ★Applying NV Energy''s own published haircuts, this 16.53 GW of requests is worth roughly 3-9 GW in the forecast depending on each project''s stage - the register''s thesis, quantified by the filer. ★CONTEXT FROM THE SAME FILING, VERBATIM: "Data centers currently account for five percent of total NV Energy sales - three percent of total Nevada Power sales and 10 percent of total Sierra sales. By 2046, it is projected that data centers will account for 64 percent of total NV Energy sales - 42 percent at Nevada Power and 82 percent at Sierra." Also VERBATIM: "effectively requiring the Companies to serve loads roughly 2.5 times current levels by 2046". ★AS-OF PROVENANCE: the volume prints no filing date on its face (docket shown as "Docket No. 26-05___", number not yet assigned). 2026-05-06 is the PDF CreationDate; the latest date referenced inside the document is 2026-04-30.','claude-opus-5 2026-07-28 (PUCN IRP volume fetched from nvenergy.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('NV Energy (Nevada Power + Sierra Pacific)','NV','non-ISO (WECC; NVE BA)',6,'2026-05-06','https://www.nvenergy.com/publish/content/dam/nvenergy/brochures_arch/about-nvenergy/rates-regulatory/recent-regulatory-filings/2026-irp/NPC-SPPC-Volume-6.pdf','Nevada Power Company and Sierra Pacific Power Company (both d/b/a NV Energy), Joint Application for approval of their 2027-2046 Integrated Resource Plan, Docket No. 26-05, Volume 6 of 41 (Summary), before the Public Utilities Commission of Nevada, Section I Executive Summary','state-PUC Integrated Resource Plan (PUCN Docket 26-05, 2026 Joint IRP)','EXECUTED Rule 9 agreements - INFRASTRUCTURE ONLY, not power supply','VERBATIM: "has executed approximately 6 GW of signed Rule 9 agreements (generally consisting of master planned community ("MPC") umbrella agreements, substation high voltage distribution ("SHVD") agreements, and high voltage distribution ("HVD") agreements) to facilitate the transmission, substation, and high voltage distribution infrastructure needed to interconnect these large loads. These agreements do not address generation and electric supply." ★★CRITICAL LIMIT ON THE 6 GW - IT DOES NOT MEAN 6 GW OF POWER IS COMMITTED. VERBATIM: "These agreements do not address generation and electric supply." Rule 9 agreements are INFRASTRUCTURE agreements (master planned community umbrella, substation high voltage distribution, and high voltage distribution) that facilitate interconnection only. This is weaker than a Duke/PPL ESA, a Dominion ESA or an Exelon TSA, all of which are supply contracts. Do not file it alongside them as an equivalent commitment. ★27% of the 22 GW of interest inquiries has reached even this infrastructure-only stage. ★★★THE MOST IMPORTANT SENTENCE IN THIS ENTIRE REGISTER - A UTILITY PUBLISHING ITS OWN HAIRCUT, TIERED BY COMMITMENT LEVEL. VERBATIM: "Consistent with past practice, these requests are scaled down in the retail load forecast. The loads of projects in the study phase saw an average overall reduction of 83 percent; the loads of projects with signed Rule 9 agreements were reduced by 38 percent." Footnote 7 refines it, VERBATIM: "The adjustment percentages will vary by individual project and year. The overall percentages include one customer who signed a letter of intent and is included at 100 percent of their request. Excluding this customer, the overall average reduction percentage for projects with a signed agreement is approximately 43 percent in this load forecast update." ★★SO THE DISCOUNT CURVE IS NOW EMPIRICAL, NOT INFERRED: study-phase requests are worth ~17% of face value and signed-agreement requests ~57-62%. Every other row in this table shows the gap between headline and forecast; NV Energy prints the multiplier itself. ★AS-OF PROVENANCE: the volume prints no filing date on its face (docket shown as "Docket No. 26-05___", number not yet assigned). 2026-05-06 is the PDF CreationDate; the latest date referenced inside the document is 2026-04-30.','claude-opus-5 2026-07-28 (PUCN IRP volume fetched from nvenergy.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ── Santee Cooper / 2025 IRP Update, SCPSC Docket 2025-18-E (added 2026-07-28,
-- batch 2). Only state-owned (non-investor-owned) utility in the register, and the
-- smallest by an order of magnitude -- useful as a scale control against Georgia
-- Power's 73.1 GW in the same SERC footprint.
-- ★★★ METHODOLOGICALLY THE BEST TREATMENT FOUND: rather than publishing the sum of
-- requests, Santee Cooper runs 50,000 Monte Carlo trials over 24 potential customers
-- (2-500 MW each) on siting probability, size and timing, and BOOKS THE 50TH
-- PERCENTILE. High Case = 95th pct = 1,536 MW total; Low Case = 1st pct = 101 MW.
-- Together with NV Energy's published 83%/38% haircuts, this is the honest end of the
-- disclosure spectrum this table exists to measure.
-- ★★ AND IT PUBLISHES DOWNSIDE: the Low Case also books LOSING 400 MW of existing
-- industrial load. No other utility in the register publishes a downside case.
-- ★★ TRAP: a FALLING stochastic number here means load became MORE certain (signed
-- contracts graduate out of the stochastic model into the conventional forecast, worth
-- ~220 MW between the 2024 and 2025 updates) -- not that demand shrank.
-- ★ NOT data-centre-attributed ("industrial and other customers"), and stated on a
-- COINCIDENT PEAK DEMAND basis, so not directly comparable with capacity-basis rows.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Santee Cooper (+ Central member cooperatives)','SC','non-ISO (SERC)',1.536,'2025-11-21','https://www.santeecooper.com/About/Integrated-Resource-Plan/presentations/Santee-Cooper-2025-IRP-Update.pdf','Santee Cooper, Integrated Resource Plan 2025 Update, section "Potential New Large Load Customers" / Figure 8 "Range of Projected Potential New Large Loads", electronically filed SCPSC Docket No. 2025-18-E, 2025-11-21, High Case','state-PUC Integrated Resource Plan update (SCPSC Docket 2025-18-E)','HIGH CASE - 95th percentile stochastic outcome, total new large loads by 2044','VERBATIM: "For purposes of the High Case scenario, Santee Cooper used the 95th percentile outcome, which reflected 671 MW of additional new large loads by 2044 for a total of 1,536 MW of new large loads (on a coincident peak demand basis)." ★NOTE THE BASIS: COINCIDENT PEAK DEMAND, not nameplate or contracted capacity - not directly comparable with the capacity-basis rows elsewhere in this table (e.g. Dominion 47 GW). ★★★THE ONLY UTILITY IN THIS REGISTER THAT PUBLISHES A PROBABILITY DISTRIBUTION INSTEAD OF A HEADLINE. VERBATIM: "Santee Cooper''s stochastic approach evaluated 24 potential customers ranging in size from 2 MW to 500 MW. Like in the load forecast used in the 2024 IRP Update, after evaluating the results of 50,000 trials, Santee Cooper chose to include the 50th percentile outcome in its load forecast." ★★This is the FORMAL version of what every other row in this table shows informally: instead of quoting the sum of requests and then quietly discounting it, Santee Cooper Monte-Carlos siting probability, project size and timing and books the MEDIAN. NV Energy''s published 83%/38% haircuts and this stochastic median are the two most methodologically honest treatments found across all 14 utilities. ★★NOT DATA-CENTRE-SPECIFIC. The section is headed "POTENTIAL NEW LARGE LOAD CUSTOMERS" and describes "inquiries for potential service from industrial and other customers with substantial energy requirements" - no data-centre attribution. Do not restate as data-centre load. Same discipline as the Georgia Power 8,448 MW and APS rows. ★A GRADUATION MECHANIC WORTH KNOWING, VERBATIM: "several large potential loads signed contracts in Santee Cooper or Central member cooperative service territory, necessitating their removal from the stochastic model and their inclusion in the conventional load forecast. Thus, the stochastic results for the 2025 Load Forecast are lower than the forecast used in the 2024 IRP Update by about 220 MW; however, this is the result of load becoming more certain." ★★SO A FALLING SPECULATIVE NUMBER HERE MEANS LOAD GOT MORE CERTAIN, NOT THAT DEMAND SHRANK - the exact inverse of the naive reading, and a trap for any trend line built on this series. ★SMALLEST UTILITY IN THE REGISTER BY AN ORDER OF MAGNITUDE, and the only one that is state-owned rather than investor-owned - useful as a scale control: 1.5 GW here versus 73.1 GW at Georgia Power next door in the same SERC footprint. ★FRESHNESS: this is the 2025 IRP Update (filed 2025-11-21), the oldest source in the register. Santee Cooper''s next triennial IRP is due September 2026 and should supersede it; it also enacted a new large-load rate class (>=50 MW, four-year experimental basis) at its 2026-04-25 board meeting, which post-dates this filing.','claude-opus-5 2026-07-28 (IRP PDF fetched from santeecooper.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Santee Cooper (+ Central member cooperatives)','SC','non-ISO (SERC)',0.101,'2025-11-21','https://www.santeecooper.com/About/Integrated-Resource-Plan/presentations/Santee-Cooper-2025-IRP-Update.pdf','Santee Cooper, Integrated Resource Plan 2025 Update, section "Potential New Large Load Customers" / Figure 8 "Range of Projected Potential New Large Loads", electronically filed SCPSC Docket No. 2025-18-E, 2025-11-21, Low Case','state-PUC Integrated Resource Plan update (SCPSC Docket 2025-18-E)','LOW CASE - 1st percentile stochastic outcome, new large loads','VERBATIM: "For the Low Case scenario, Santee Cooper used the results near the minimum stochastic outcome (i.e., the 1st percentile), which represents 101 MW of new large loads. Furthermore, the Low Case includes a 400 MW reduction representing the loss of a very large, or several smaller industrial customers in Santee Cooper or Central member cooperative territory." ★★THE MOST UNDER-REPORTED NUMBER IN THE WHOLE REGISTER: a utility formally planning for the possibility that new large load arrives at 101 MW - 6.6% of its own High Case - AND that it LOSES 400 MW of existing industrial load. Every other utility here publishes only upside. ★Low Case is 15.2x smaller than High Case, the widest published uncertainty band in the table. ★★★THE ONLY UTILITY IN THIS REGISTER THAT PUBLISHES A PROBABILITY DISTRIBUTION INSTEAD OF A HEADLINE. VERBATIM: "Santee Cooper''s stochastic approach evaluated 24 potential customers ranging in size from 2 MW to 500 MW. Like in the load forecast used in the 2024 IRP Update, after evaluating the results of 50,000 trials, Santee Cooper chose to include the 50th percentile outcome in its load forecast." ★★This is the FORMAL version of what every other row in this table shows informally: instead of quoting the sum of requests and then quietly discounting it, Santee Cooper Monte-Carlos siting probability, project size and timing and books the MEDIAN. NV Energy''s published 83%/38% haircuts and this stochastic median are the two most methodologically honest treatments found across all 14 utilities. ★★NOT DATA-CENTRE-SPECIFIC. The section is headed "POTENTIAL NEW LARGE LOAD CUSTOMERS" and describes "inquiries for potential service from industrial and other customers with substantial energy requirements" - no data-centre attribution. Do not restate as data-centre load. Same discipline as the Georgia Power 8,448 MW and APS rows. ★SMALLEST UTILITY IN THE REGISTER BY AN ORDER OF MAGNITUDE, and the only one that is state-owned rather than investor-owned - useful as a scale control: 1.5 GW here versus 73.1 GW at Georgia Power next door in the same SERC footprint. ★FRESHNESS: this is the 2025 IRP Update (filed 2025-11-21), the oldest source in the register. Santee Cooper''s next triennial IRP is due September 2026 and should supersede it; it also enacted a new large-load rate class (>=50 MW, four-year experimental basis) at its 2026-04-25 board meeting, which post-dates this filing.','claude-opus-5 2026-07-28 (IRP PDF fetched from santeecooper.com + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ═══════════════════════════════════════════════════════════════════════════════
-- BATCH 2 CLOSE-OUT (2026-07-28): register at 35 rows / 13 utility entities.
--
-- ★★★ WHERE THE NUMBERS ACTUALLY LIVE -- ranked by hit rate, revised after batch 2.
-- Batch 1 concluded "EDGAR 8-K exhibit 99.2 is the path". Batch 2 says that is the
-- EXCEPTION, not the rule: Exelon and Pinnacle West were the only two utilities whose
-- figures were on EDGAR at all. The reliable channels, in order:
--   1. STATE-PUC FILINGS (best; regulator-compelled, dated, and they disclose the
--      caveats): Georgia PSC Docket 55378 quarterly Large Load reports, NV Energy
--      PUCN IRP Docket 26-05, Santee Cooper SCPSC 2025-18-E. These gave the ONLY
--      published haircut rates and the ONLY stochastic treatment found.
--   2. IR-CDN DECKS (high hit rate, but you must find the CDN -- IR landing pages are
--      JS-rendered or bot-walled): Duke s201.q4cdn.com, PPL investors.pplweb.com,
--      Entergy s201.q4cdn.com, Xcel s202.q4cdn.com. WebSearch for
--      '"q4cdn.com" <utility> <quarter> presentation pdf' resolves these fast.
--   3. EDGAR (LOW hit rate for load figures): only Exelon (8-K ex99.2) and Pinnacle
--      West (8-K item 7.01 "mayinvestordeck.htm") publish them there. Earnings
--      PRESS RELEASES essentially never carry a GW load figure -- checked and empty
--      for Southern, Xcel, PPL, Entergy, Duke, Evergy, and Sempra.
--
-- ★★★ THE TWO RULES THAT CHANGED HOW ROWS ARE READ:
--   * NESTED vs INCREMENTAL tiers. Duke: "15.4 GW pipeline INCLUDES 7.6 GW ESAs, OF
--     WHICH 5 GW under construction" -- subsets, never add. Xcel: ~2 GW contracted
--     PLUS ~4 GW target PLUS >20 GW "Additional Pipeline" -- increments. Same funnel
--     graphic, opposite arithmetic. Always read the connective words.
--   * "NO PRIMARY FIGURE" IS A VERDICT ON THE CHANNEL, NOT ON THE UTILITY. Duke was
--     rejected twice and PPL twice on their SEC filings; both had full ladders sitting
--     in IR-CDN decks the whole time. Re-check the CDN before concluding absence.
--     PPL's "4 conflicting figures" turned out to be ONE bar chart sampled at four
--     different quarters.
--
-- ★★ STILL REJECTED after batch 2 -- no primary GW figure in any channel checked:
--   * EVERGY -- checked Q1-2026 8-K ex99.1 (announces an ESA signing, states NO MW),
--     the Q1-2026 10-Q (only 15,800 MW of OWNED GENERATION), and its 8-K history (no
--     deck filed). investors.evergy.com is bot-walled: both WebFetch and a real
--     browser return "Page Not Found" with a single link, and static-file URLs return
--     empty to curl. Secondary reports ~3 GW from five ESAs and ">10 GW" remaining
--     pipeline -- NOT inserted. NEXT: Kansas CC / Missouri PSC filings, or the deck
--     via a channel that survives the wall.
--   * TVA -- Q1-2026 10-Q (2026-05-05) carries only risk boilerplate and a nuclear
--     narrative; no data-centre GW. Secondary "11,000 MW if all interested data
--     centres were approved" is unattributed. NEXT: TVA board presentations / 2026 IRP.
--   * SEMPRA (as an Oncor cross-check) -- Q1-2026 8-K ex99.1 has ZERO GW/gigawatt/
--     "data cent" matches, and Sempra files no deck on EDGAR. Oncor's own quarterly
--     results remain the better primary; no cross-check was obtainable.
-- ═══════════════════════════════════════════════════════════════════════════════

-- ── Evergy Metro / Missouri PSC EFIS, 2026 Annual Update IRP (added 2026-07-28,
-- batch 3). ★★★ CLEARS THE LAST STANDING REJECTION IN THIS TABLE. Evergy was
-- rejected twice: its 8-K ex99.1 announces an ESA signing with NO MW, its 10-Q shows
-- only 15,800 MW of OWNED GENERATION, it files no deck on EDGAR, and
-- investors.evergy.com is bot-walled to both WebFetch and a real browser. The figures
-- were in a state-PUC filing the whole time -- the third consecutive utility (after
-- Georgia Power and NV Energy) where the commission, not the company, was the source.
-- ★★ EVERGY DISCLOSES AN ADMISSION TEST WHERE NV ENERGY DISCLOSES A PERCENTAGE:
-- a project enters base planning only on service-commenced / ESA-executed / SPP study
-- finished. Binary and named, rather than an 83%/38% haircut. Both forms of honest
-- disclosure are now represented in the register.
-- ★★★ AND THE TEST BITES: all four Table 45 pipeline customers show "No" for BOTH the
-- Evergy and the SPP interconnection study, so the entire 2,416 MW pipeline sits below
-- Evergy's own threshold and NONE of it is in the forecast. ~900 MW is.
-- ★★ SCOPE TRAP: Metro only (EMM + EKM). Evergy Missouri West and Evergy Kansas
-- Central are NOT covered. Secondary "~15 GW pipeline / ~5 GW advanced" is
-- company-wide and must never be compared with these Metro numbers.
-- ★ TRAP: this IRP's Plans CCAA/DCAA/ECAA model hypothetical ADDITIONAL load of
-- 750 MW / 1,000 MW / 1.5 GW. Those are expansion sensitivities, not customer
-- requests, and quoting them as demand would be fabrication.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Evergy Metro (Missouri Metro + Kansas Metro)','MO/KS','SPP',2.416,'2026-05-01','https://efis.psc.mo.gov/Document/Display/876123','Evergy Missouri Metro, 2026 Annual Update Integrated Resource Plan (May 2026, Public), filed with the Missouri PSC via EFIS, Table 45 ''Metro Large Load Customer Pipeline'' (section 14.2)','state-PUC Integrated Resource Plan annual update (Missouri PSC / EFIS)','PIPELINE at 2033 - requested ramp, ZERO interconnection studies complete','VERBATIM (Table 45, columns 2028-2033 in MW): "Company A / EMM / Data Center / No / No / 250 500 750 1,000 1,000 1,000"; "Company B / EKM / Manufacturing / No / No / 40 40 40 40 40 40"; "Company C / EKM / Data Center / No / No / 96 192 288 396 540 576"; "Company D / EKM / Data Center / No / No / 275 575 800 800 800 800"; total row "661 1,307 1,878 2,236 2,380 2,416". This row is the 2033 total. ★★★THE HARDEST FACT IN TABLE 45: all four pipeline customers show "No" under BOTH "Evergy Complete?" and "SPP Complete?" for interconnection studies. NOT ONE has finished either study - so the entire 2,416 MW pipeline sits below Evergy''s own stated admission threshold and none of it is in the forecast. Evergy also warns, VERBATIM: "The ability to meet the customer''s desired ramp will be heavily dependent upon transmission infrastructure requirements and timing for delivery of interconnection facilities and transmission network upgrades. Additionally, generation capacity to meet the customer''s ramp may not be available on the timeline requested." Table footnote: "*Load request information based on most recent customer engagement and subject to change." ★2.7x the ~900 MW Evergy actually admits to its forecast. ★★★EVERGY PUBLISHES AN ADMISSION TEST, WHERE NV ENERGY PUBLISHES A PERCENTAGE - the two ways a utility can disclose its own discount, and both are now in this register. VERBATIM: "While Evergy has a robust pipeline of prospective large load customers, only customers who meet critical criteria and milestones within Evergy''s established review process are included in base load planning to avoid exposing our Preferred Plan to unnecessary risks. Generally, for a large load to be included into base load IRP planning, Evergy expects that a large load customer project have met at least one of the following criteria: recently commenced electric service from Evergy, an executed ESA under the LLPS tariff, or have a finalized SPP load addition study (typically Attachment AQ) and expect to have an executed LLPS ESA within the next 3-6 months." ★So the gate is BINARY and named, not a haircut: a project is either in the forecast or it is not, and the test is service commenced / ESA executed / SPP study finished. ★★SCOPE - METRO ONLY, NOT ALL OF EVERGY. This IRP covers Evergy Missouri Metro (EMM) and Evergy Kansas Metro (EKM). Evergy also operates Evergy Missouri West and Evergy Kansas Central, which are NOT in this document. Secondary coverage of a ''~15 GW Evergy large load pipeline, ~5 GW advanced'' is company-wide and MUST NOT be compared with these Metro figures - they measure different territories. ★★DO NOT MINE THIS IRP''S SCENARIO PLANS FOR LOAD FIGURES: Plans CCAA / DCAA / ECAA model hypothetical ADDITIONAL load of 750 MW, 1,000 MW and 1.5 GW respectively. Those are capacity-expansion sensitivities, NOT customer requests, and would be a pure fabrication if quoted as demand. ★AS-OF PROVENANCE: the cover page prints only "May 2026" (no day) and the PDF carries no creation-date metadata, so 2026-05-01 is a month-precision placeholder, not an exact filing date. Table 45''s ramp columns run 2028-2033.','claude-opus-5 2026-07-28 (IRP PDF fetched from Missouri PSC EFIS + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Evergy Metro (Missouri Metro + Kansas Metro)','MO/KS','SPP',2.376,'2026-05-01','https://efis.psc.mo.gov/Document/Display/876123','Evergy Missouri Metro, 2026 Annual Update Integrated Resource Plan (May 2026, Public), filed with the Missouri PSC via EFIS, Table 45, data-centre rows only (Companies A, C, D)','state-PUC Integrated Resource Plan annual update (Missouri PSC / EFIS)','PIPELINE at 2033, DATA-CENTRE customers only (A+C+D)','VERBATIM (Table 45): Company A "Data Center" 1,000 MW at 2033, Company C "Data Center" 576 MW at 2033, Company D "Data Center" 800 MW at 2033 = 2,376 MW; the only non-data-centre entry is Company B, "Manufacturing", flat at 40 MW. ★★DATA-CENTRE SHARE BY MW, FROM A NAMED CUSTOMER-TYPE COLUMN: 2,376 of 2,416 MW = 98.3%. Comparable in quality to NV Energy (16,530/16,930 = 97.6%) and far stronger than Georgia Power, where per-project MW is redacted and only a project COUNT share exists. ★Arithmetic is mine (summing the three rows Evergy labels "Data Center"); the per-customer MW and the type labels are verbatim. ★★★THE HARDEST FACT IN TABLE 45: all four pipeline customers show "No" under BOTH "Evergy Complete?" and "SPP Complete?" for interconnection studies. NOT ONE has finished either study - so the entire 2,416 MW pipeline sits below Evergy''s own stated admission threshold and none of it is in the forecast. Evergy also warns, VERBATIM: "The ability to meet the customer''s desired ramp will be heavily dependent upon transmission infrastructure requirements and timing for delivery of interconnection facilities and transmission network upgrades. Additionally, generation capacity to meet the customer''s ramp may not be available on the timeline requested." Table footnote: "*Load request information based on most recent customer engagement and subject to change." ★★SCOPE - METRO ONLY, NOT ALL OF EVERGY. This IRP covers Evergy Missouri Metro (EMM) and Evergy Kansas Metro (EKM). Evergy also operates Evergy Missouri West and Evergy Kansas Central, which are NOT in this document. Secondary coverage of a ''~15 GW Evergy large load pipeline, ~5 GW advanced'' is company-wide and MUST NOT be compared with these Metro figures - they measure different territories. ★AS-OF PROVENANCE: the cover page prints only "May 2026" (no day) and the PDF carries no creation-date metadata, so 2026-05-01 is a month-precision placeholder, not an exact filing date. Table 45''s ramp columns run 2028-2033.','claude-opus-5 2026-07-28 (IRP PDF fetched from Missouri PSC EFIS + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Evergy Metro (Missouri Metro + Kansas Metro)','MO/KS','SPP',0.9,'2026-05-01','https://efis.psc.mo.gov/Document/Display/876123','Evergy Missouri Metro, 2026 Annual Update Integrated Resource Plan (May 2026, Public), filed with the Missouri PSC via EFIS, Section 3 Load Analysis and Load Forecasting Update','state-PUC Integrated Resource Plan annual update (Missouri PSC / EFIS)','ADMITTED TO BASE PLANNING - 3 customers passing Evergy''s criteria (firmest rung)','VERBATIM: "Evergy Metro has three specific large load customers that meet the criteria for base load planning and have been incorporated in all load forecast scenarios (low, mid, high) for the 2026 Annual Update." and "The total combined peak of these three large load customers is projected to be approximately 900 MW at steady state." ★★THE NUMBER EVERGY ACTUALLY PLANS TO - the Metro analogue of Dominion 16.6 GW and Georgia Power 7,800 MW. ★THE THREE, per the filing: (1) largest, in EMM, "currently using electricity for active site construction, executed an LLPS ESA in the first quarter of 2026"; (2) a second, smaller EMM project "already online and receiving service under an existing Large Power Service tariff due to the current peak MW being projected below the 75 MW threshold for LLPS qualification" - these two are "nearly 90% of the total large load incorporated into Metro''s 2026 IRP base load forecast"; (3) an EKM project, "not yet online but has fully completed the required SPP load addition study (Attachment AQ)... in the final commercial negotiation stage", expected to execute an ESA later in 2026, the remaining 10%. ★★SO ONLY ~810 MW IS ONLINE-OR-CONTRACTED AND ~90 MW IS STILL PRE-CONTRACT. ★★★EVERGY PUBLISHES AN ADMISSION TEST, WHERE NV ENERGY PUBLISHES A PERCENTAGE - the two ways a utility can disclose its own discount, and both are now in this register. VERBATIM: "While Evergy has a robust pipeline of prospective large load customers, only customers who meet critical criteria and milestones within Evergy''s established review process are included in base load planning to avoid exposing our Preferred Plan to unnecessary risks. Generally, for a large load to be included into base load IRP planning, Evergy expects that a large load customer project have met at least one of the following criteria: recently commenced electric service from Evergy, an executed ESA under the LLPS tariff, or have a finalized SPP load addition study (typically Attachment AQ) and expect to have an executed LLPS ESA within the next 3-6 months." ★So the gate is BINARY and named, not a haircut: a project is either in the forecast or it is not, and the test is service commenced / ESA executed / SPP study finished. ★The LLPS (Large Load Power Service) tariff referenced throughout is the one approved by the Kansas Corporation Commission in docket 25EKME315TAR (>=75 MW peak, 12-17 year contract terms with early-termination fees); Missouri''s counterpart is Case No. EO-2025-0154. The second EMM customer below is explicitly NOT on LLPS because it sits under the 75 MW threshold. ★★SCOPE - METRO ONLY, NOT ALL OF EVERGY. This IRP covers Evergy Missouri Metro (EMM) and Evergy Kansas Metro (EKM). Evergy also operates Evergy Missouri West and Evergy Kansas Central, which are NOT in this document. Secondary coverage of a ''~15 GW Evergy large load pipeline, ~5 GW advanced'' is company-wide and MUST NOT be compared with these Metro figures - they measure different territories. ★AS-OF PROVENANCE: the cover page prints only "May 2026" (no day) and the PDF carries no creation-date metadata, so 2026-05-01 is a month-precision placeholder, not an exact filing date. Table 45''s ramp columns run 2028-2033.','claude-opus-5 2026-07-28 (IRP PDF fetched from Missouri PSC EFIS + pdftotext -layout + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;

-- ═══════════════════════════════════════════════════════════════════════════════
-- BATCH 3 CLOSE-OUT (2026-07-28): register at 38 rows / 14 utility entities.
--
-- ★★★ SUPERSEDES THE EVERGY REJECTION RECORDED IN THE BATCH-2 CLOSE-OUT ABOVE.
-- That block says Evergy has "no primary GW figure in any channel checked". That was
-- true of every channel it named (8-K, 10-Q, IR site, deck) and FALSE as a
-- conclusion. Evergy Missouri Metro's 2026 Annual Update IRP, filed with the Missouri
-- PSC and served publicly through EFIS, carries a per-customer MW table.
--
-- ★★★ THAT IS NOW THREE FOR THREE. Georgia Power, NV Energy and Evergy were each
-- unobtainable from the company and routine from the commission. Combined with the
-- batch-2 finding that only 2 of 13 utilities publish load figures on EDGAR, the
-- rule for this table is settled: START AT THE STATE COMMISSION, not the filer.
--   Georgia PSC  -> psc.ga.gov FACTS document service (Docket 55378)
--   PUCN         -> nvenergy.com regulatory-filings mirror (Docket 26-05)
--   Missouri PSC -> efis.psc.mo.gov/Document/Display/<id>  (direct, no bot wall)
-- Evergy's investor site is bot-walled to WebFetch AND to a real browser; its
-- regulator's document server answered a plain curl on the first try.
--
-- ★★ TWO SHAPES OF HONEST DISCLOSURE, BOTH NOW REPRESENTED:
--   * NV Energy publishes a PERCENTAGE -- study-phase requests cut 83%, signed 38%.
--   * Evergy publishes an ADMISSION TEST -- a project enters base planning only on
--     service commenced / LLPS ESA executed / SPP load-addition study finished.
--   And Evergy's test bites: all four Table 45 pipeline customers show "No" for BOTH
--   the Evergy and the SPP study, so the whole 2,416 MW pipeline is outside the
--   forecast while ~900 MW is inside it.
--
-- ★★ SCOPE TRAP ON THE EVERGY ROWS: they are Evergy METRO (EMM + EKM) only. Evergy
-- Missouri West and Evergy Kansas Central are not in this document. The widely quoted
-- "~15 GW Evergy pipeline / ~5 GW advanced" is company-wide -- different territory,
-- not a contradiction, and never to be compared row-to-row.
--
-- ★ STILL REJECTED: TVA (10-Q is risk boilerplate; try board decks / 2026 IRP) and
-- SEMPRA as an Oncor cross-check (zero GW matches, no deck on EDGAR). On the evidence
-- above, the next channel to try for TVA is the commission-equivalent -- its IRP and
-- board materials -- not its SEC filings.
-- ═══════════════════════════════════════════════════════════════════════════════

-- ── Tennessee Valley Authority / Investor Presentation June 2026 (added 2026-07-28,
-- batch 4). ★★ CLEARS THE TVA REJECTION -- but NOT with the kind of number the earlier
-- close-outs were looking for, and the distinction matters more than the row does.
-- ★★★ THIS IS THE REGISTER'S ONLY PURE AS-BUILT FIGURE: 1.2 GW of data-centre demand
-- that EXISTS AND IS BEING SERVED TODAY, not requested, queued, committed or forecast.
-- Never compare it with a pipeline row (Georgia Power 73.1, Oncor 271); its only fair
-- comparators are the "under construction" rungs, and really nothing else here.
-- ★★★ TVA PUBLISHES NO DATA-CENTRE PIPELINE MW AT ALL. Exhaustively checked: 10-Q,
-- IRP Vol 1 (242pp -- ZERO occurrences of "large load"; of 92 MW/GW figures in a
-- demand context, none within 260 chars of "data cent"), IRP exec summary, overview,
-- FAQs and the July-2 webinar deck. Its famous 7-26 GW gas / 11-32 GW capacity numbers
-- are GENERATION BUILD -- the same trap that rejected Entergy's Meta announcement.
-- ★ STRUCTURAL REASON: TVA is federal, sells wholesale to 153 local power companies,
-- and any customer over 100 MW needs BOARD approval -- so load requests are board
-- actions, not IRP line items. The August 2026 board vote creates a data-centre rate
-- class WITH a financial commitment for new load; that is the instrument likely to
-- produce a countable committed-MW figure. RE-CHECK AFTER AUGUST 2026.
-- ★ CHANNEL NOTE: tva.com 403s to curl and to WebFetch and its board page renders
-- empty in a real browser, but both CDNs (s205.q4cdn.com for IR, azureedge.net for the
-- IRP) serve fine. Third utility in a row where the company's own site was the wall.
INSERT INTO utility_load_requests (utility,state,iso,gw_requested,as_of_date,source_url,source_title,filing_type,request_type,notes,verified_by) VALUES ('Tennessee Valley Authority','TN/AL/MS/KY/GA/NC/VA','non-ISO (TVA BA, SERC)',1.2,'2026-06-15','https://s205.q4cdn.com/318912997/files/doc_presentations/2026/Jun/15/TVA-Briefing-for-the-Financial-Community.pdf','Tennessee Valley Authority, Investor Presentation June 2026 ("TVA Briefing for the Financial Community"), slide 11 "Data Center Growth Reshaping TVA''s Energy Landscape"','investor presentation (TVA briefing for the financial community)','EXISTING in-service data-centre demand (REALIZED, not a request or pipeline)','VERBATIM: "Data Center Growth Reshaping TVA''s Energy Landscape - With over 9,000 GWh of usage and 1,200 MW of demand, data centers have become TVA''s largest industrial sector and a key driver of sustained load growth." ★★★THIS IS A DIFFERENT KIND OF NUMBER FROM EVERY OTHER ROW IN THE REGISTER - READ THE request_type BEFORE USING IT. Almost every other row is a REQUEST, PIPELINE, COMMITMENT or FORECAST, i.e. load that does not yet exist. This 1.2 GW is REALIZED, IN-SERVICE demand that data centres are drawing from TVA today. It is therefore NOT comparable with Georgia Power''s 73.1 GW pipeline or Oncor''s 271 GW of requests, and it is NOT TVA''s pipeline - TVA publishes no data-centre pipeline MW anywhere (see the exhaustion note below). Its natural comparators are the ''under construction'' rungs (Duke 5 GW, PPL PA 5 GW, Georgia Power 8.5 GW) and, better still, nothing else here at all - it is the only pure as-built figure in the table. ★TRAJECTORY FROM THE SAME SLIDE (data-centre energy, GWh by year, verbatim series): 90 (2015), 159, 156, 268, 499 (2019), 1,269, 2,730, 4,538, 5,435, 6,732, 9,156 (2025). That is a 102x increase in a decade and a 36% jump in the last year alone. ★SHARE: the slide''s two donuts show total industrial usage 40,077 GWh in 2019 with data centres at 1%, versus 47,742 GWh in 2025 with data centres at 19%. VERBATIM: "Data Centers are now the largest industrial segment." and "Industrial customers make up ~30% of TVA''s total load." ★So data centres are ~19% of ~30% = roughly 5.7% of TVA''s total load - almost exactly NV Energy''s disclosed 5% today, the only other realized-share figure in the register. ★★★CHANNEL EXHAUSTION RECORD - TVA PUBLISHES NO DATA-CENTRE PIPELINE MW. Checked on 2026-07-28: (1) Q1-2026 10-Q - risk boilerplate and a nuclear narrative only; (2) 2026 IRP Volume 1, 242pp - 14 ''data cent'' mentions, ZERO occurrences of the phrase ''large load'', and of 92 MW/GW figures appearing in a demand or load context, NOT ONE falls within 260 characters of ''data cent''; (3) IRP Executive Summary (15pp), (4) IRP Overview (4pp), (5) IRP FAQs (15pp), (6) July-2 public webinar deck (37pp) - every data-centre mention in all four is qualitative, with no MW or GW anywhere in its window. TVA''s widely quoted 7-26 GW gas / 11-32 GW new capacity figures are GENERATION BUILD, the same trap that rejected Entergy''s Meta announcement. ★STRUCTURAL REASON: TVA is a federal corporation selling wholesale to 153 local power companies, and any prospective customer above 100 MW requires TVA BOARD approval - so load requests surface as board actions, not as an IRP line item. ★NEXT PLACE TO LOOK for a TVA pipeline figure: the August 2026 Board meeting. The IRP FAQs say, VERBATIM: "At the August Board meeting, the TVA Board will vote on pricing actions... This will include a new rate specifically for all data center customers, along with a financial commitment for new and expanding data center loads." A new data-centre rate class plus a financial-commitment requirement is exactly the instrument that creates a countable committed-MW figure, as LLPS did for Evergy and ELOA/CLOA/ESA did for Dominion. Re-check after the August 2026 board vote. ★tva.com itself 403s to curl AND to WebFetch, and its board-meeting page renders empty in a real browser; the IR CDN (s205.q4cdn.com) and the Azure CDN that serves the IRP PDFs both answer normally. ★AS-OF PROVENANCE: deck cover reads "Investor Presentation June 2026" and the PDF CreationDate is 2026-06-15, which is the date stored. The underlying data pairs with the chart''s 2025 column (9,156 GWh), and TVA''s fiscal year ends 30 September - so the measurement period is FY2025, not June 2026. Do not read this as a June-2026 instantaneous reading.','claude-opus-5 2026-07-28 (investor deck fetched from TVA IR CDN + pdftotext -layout page 11 + verbatim-quoted)') ON CONFLICT (utility, as_of_date, gw_requested) DO NOTHING;
